public void testDesc() {
    final String sql = "select desc\n" + "from t\n" + "order by desc asc, desc desc";
    final String expected = "SELECT `DESC`\n" + "FROM `T`\n" + "ORDER BY `DESC`, `DESC` DESC";
    sql(sql).ok(expected);
}

/**
 * This is a failure test making sure the LOOKAHEAD for WHEN clause is 2 in Babel, where
 * in core parser this number is 1.
 *
 * @see SqlParserTest#testCaseExpression()
 * @see <a href="https://issues.apache.org/jira/browse/CALCITE-2847">[CALCITE-2847]
 * Optimize global LOOKAHEAD for SQL parsers</a>
 */
@Test
public void testCaseExpressionBabel() {
    checkFails("case x when 2, 4 then 3 ^when^ then 5 else 4 end", "(?s)Encountered \"when then\" at .*");
}

