@Test
public void testStrings() {
    ArrayTable.Column pair;
    final ColumnLoader.ValueSet valueSet = new ColumnLoader.ValueSet(String.class);
    valueSet.add("foo");
    valueSet.add("foo");
    pair = valueSet.freeze(0, null);
    assertTrue(pair.representation instanceof ArrayTable.ObjectArray);
    final ArrayTable.ObjectArray representation = (ArrayTable.ObjectArray) pair.representation;
    assertEquals("foo", representation.getObject(pair.dataSet, 0));
    assertEquals("foo", representation.getObject(pair.dataSet, 1));
    assertEquals(1, pair.cardinality);
    // Large number of the same string. ObjectDictionary backed by Constant.
    for (int i = 0; i < 2000; i++) {
        valueSet.add("foo");
    }
    pair = valueSet.freeze(0, null);
    final ArrayTable.ObjectDictionary representation2 = (ArrayTable.ObjectDictionary) pair.representation;
    assertTrue(representation2.representation instanceof ArrayTable.Constant);
    assertEquals("foo", representation2.getObject(pair.dataSet, 0));
    assertEquals("foo", representation2.getObject(pair.dataSet, 1000));
    assertEquals(1, pair.cardinality);
    // One different string. ObjectDictionary backed by 1-bit
    // BitSlicedPrimitiveArray
    valueSet.add("bar");
    pair = valueSet.freeze(0, null);
    final ArrayTable.ObjectDictionary representation3 = (ArrayTable.ObjectDictionary) pair.representation;
    assertTrue(representation3.representation instanceof ArrayTable.BitSlicedPrimitiveArray);
    final ArrayTable.BitSlicedPrimitiveArray representation4 = (ArrayTable.BitSlicedPrimitiveArray) representation3.representation;
    assertEquals(1, representation4.bitCount);
    assertFalse(representation4.signed);
    assertEquals("foo", representation3.getObject(pair.dataSet, 0));
    assertEquals("foo", representation3.getObject(pair.dataSet, 1000));
    assertEquals("bar", representation3.getObject(pair.dataSet, 2003));
    assertEquals(2, pair.cardinality);
}

@Test
public void testAllNull() {
    ArrayTable.Column pair;
    final ColumnLoader.ValueSet valueSet = new ColumnLoader.ValueSet(String.class);
    valueSet.add(null);
    pair = valueSet.freeze(0, null);
    assertTrue(pair.representation instanceof ArrayTable.ObjectArray);
    final ArrayTable.ObjectArray representation = (ArrayTable.ObjectArray) pair.representation;
    assertNull(representation.getObject(pair.dataSet, 0));
    assertEquals(1, pair.cardinality);
    for (int i = 0; i < 3000; i++) {
        valueSet.add(null);
    }
    pair = valueSet.freeze(0, null);
    final ArrayTable.ObjectDictionary representation2 = (ArrayTable.ObjectDictionary) pair.representation;
    assertTrue(representation2.representation instanceof ArrayTable.Constant);
    assertEquals(1, pair.cardinality);
}

@Test
public void testOneValueOneNull() {
    ArrayTable.Column pair;
    final ColumnLoader.ValueSet valueSet = new ColumnLoader.ValueSet(String.class);
    valueSet.add(null);
    valueSet.add("foo");
    pair = valueSet.freeze(0, null);
    assertTrue(pair.representation instanceof ArrayTable.ObjectArray);
    final ArrayTable.ObjectArray representation = (ArrayTable.ObjectArray) pair.representation;
    assertNull(representation.getObject(pair.dataSet, 0));
    assertEquals(2, pair.cardinality);
    for (int i = 0; i < 3000; i++) {
        valueSet.add(null);
    }
    pair = valueSet.freeze(0, null);
    final ArrayTable.ObjectDictionary representation2 = (ArrayTable.ObjectDictionary) pair.representation;
    assertEquals(1, ((ArrayTable.BitSlicedPrimitiveArray) representation2.representation).bitCount);
    assertEquals("foo", representation2.getObject(pair.dataSet, 1));
    assertNull(representation2.getObject(pair.dataSet, 10));
    assertEquals(2, pair.cardinality);
}

@Test
public void testLoadSorted() {
    final JavaTypeFactoryImpl typeFactory = new JavaTypeFactoryImpl(RelDataTypeSystem.DEFAULT);
    final RelDataType rowType = typeFactory.builder().add("empid", typeFactory.createType(int.class)).add("deptno", typeFactory.createType(int.class)).add("name", typeFactory.createType(String.class)).build();
    final Enumerable<Object[]> enumerable = Linq4j.asEnumerable(Arrays.asList(new Object[] { 100, 10, "Bill" }, new Object[] { 200, 20, "Eric" }, new Object[] { 150, 10, "Sebastian" }, new Object[] { 160, 10, "Theodore" }));
    final ColumnLoader<Object[]> loader = new ColumnLoader<Object[]>(typeFactory, enumerable, RelDataTypeImpl.proto(rowType), null);
    checkColumn(loader.representationValues.get(0), ArrayTable.RepresentationType.BIT_SLICED_PRIMITIVE_ARRAY, "Column(representation=BitSlicedPrimitiveArray(ordinal=0, bitCount=8, primitive=INT, signed=false), value=[100, 150, 160, 200, 0, 0, 0, 0])");
    checkColumn(loader.representationValues.get(1), ArrayTable.RepresentationType.BIT_SLICED_PRIMITIVE_ARRAY, "Column(representation=BitSlicedPrimitiveArray(ordinal=1, bitCount=5, primitive=INT, signed=false), value=[10, 10, 10, 20, 0, 0, 0, 0, 0, 0, 0, 0])");
    checkColumn(loader.representationValues.get(2), ArrayTable.RepresentationType.OBJECT_ARRAY, "Column(representation=ObjectArray(ordinal=2), value=[Bill, Sebastian, Theodore, Eric])");
}

/**
 * As {@link #testLoadSorted()} but column #1 is the unique column, not
 * column #0. The algorithm needs to go back and permute the values of
 * column #0 after it discovers that column #1 is unique and sorts by it.
 */
@Test
public void testLoadSorted2() {
    final JavaTypeFactoryImpl typeFactory = new JavaTypeFactoryImpl(RelDataTypeSystem.DEFAULT);
    final RelDataType rowType = typeFactory.builder().add("deptno", typeFactory.createType(int.class)).add("empid", typeFactory.createType(int.class)).add("name", typeFactory.createType(String.class)).build();
    final Enumerable<Object[]> enumerable = Linq4j.asEnumerable(Arrays.asList(new Object[] { 10, 100, "Bill" }, new Object[] { 20, 200, "Eric" }, new Object[] { 30, 150, "Sebastian" }, new Object[] { 10, 160, "Theodore" }));
    final ColumnLoader<Object[]> loader = new ColumnLoader<Object[]>(typeFactory, enumerable, RelDataTypeImpl.proto(rowType), null);
    // Note that values have been sorted with {20, 200, Eric} last because the
    // value 200 is the highest value of empid, the unique column.
    checkColumn(loader.representationValues.get(0), ArrayTable.RepresentationType.BIT_SLICED_PRIMITIVE_ARRAY, "Column(representation=BitSlicedPrimitiveArray(ordinal=0, bitCount=5, primitive=INT, signed=false), value=[10, 30, 10, 20, 0, 0, 0, 0, 0, 0, 0, 0])");
    checkColumn(loader.representationValues.get(1), ArrayTable.RepresentationType.BIT_SLICED_PRIMITIVE_ARRAY, "Column(representation=BitSlicedPrimitiveArray(ordinal=1, bitCount=8, primitive=INT, signed=false), value=[100, 150, 160, 200, 0, 0, 0, 0])");
    checkColumn(loader.representationValues.get(2), ArrayTable.RepresentationType.OBJECT_ARRAY, "Column(representation=ObjectArray(ordinal=2), value=[Bill, Sebastian, Theodore, Eric])");
}

/**
 * Test case for
 * <a href="https://issues.apache.org/jira/browse/CALCITE-2677">[CALCITE-2677]
 * Struct types with one field are not mapped correctly to Java Classes</a>.
 */
@Test
public void testFieldClassOnColumnOfOneFieldStructType() {
    RelDataType columnType = TYPE_FACTORY.createStructType(ImmutableList.of(TYPE_FACTORY.createSqlType(SqlTypeName.INTEGER)), ImmutableList.of("intField"));
    RelDataType rowType = TYPE_FACTORY.createStructType(ImmutableList.of(columnType), ImmutableList.of("structField"));
    PhysType rowPhysType = PhysTypeImpl.of(TYPE_FACTORY, rowType, JavaRowFormat.ARRAY);
    assertEquals(Object[].class, rowPhysType.fieldClass(0));
}

