/**
 * Tests GROUP BY ROLLUP of two columns. The SQL for MySQL has
 * "GROUP BY ... ROLLUP" but no "ORDER BY".
 */
@Test
public void testSelectQueryWithGroupByRollup() {
    final String query = "select \"product_class_id\", \"brand_name\"\n" + "from \"product\"\n" + "group by rollup(\"product_class_id\", \"brand_name\")\n" + "order by 1, 2";
    final String expected = "SELECT \"product_class_id\", \"brand_name\"\n" + "FROM \"foodmart\".\"product\"\n" + "GROUP BY ROLLUP(\"product_class_id\", \"brand_name\")\n" + "ORDER BY \"product_class_id\", \"brand_name\"";
    final String expectedMySql = "SELECT `product_class_id`, `brand_name`\n" + "FROM `foodmart`.`product`\n" + "GROUP BY `product_class_id`, `brand_name` WITH ROLLUP";
    final String expectedMySql8 = "SELECT `product_class_id`, `brand_name`\n" + "FROM `foodmart`.`product`\n" + "GROUP BY ROLLUP(`product_class_id`, `brand_name`)\n" + "ORDER BY `product_class_id` NULLS LAST, `brand_name` NULLS LAST";
    sql(query).ok(expected).withMysql().ok(expectedMySql).withMysql8().ok(expectedMySql8);
}

