/**
 * CUBE of one column is equivalent to ROLLUP, and Calcite recognizes
 * this.
 */
@Test
public void testSelectQueryWithSingletonCube() {
    final String query = "select \"product_class_id\", count(*) as c\n" + "from \"product\"\n" + "group by cube(\"product_class_id\")\n" + "order by 1, 2";
    final String expected = "SELECT \"product_class_id\", COUNT(*) AS \"C\"\n" + "FROM \"foodmart\".\"product\"\n" + "GROUP BY ROLLUP(\"product_class_id\")\n" + "ORDER BY \"product_class_id\", COUNT(*)";
    final String expectedMySql = "SELECT `product_class_id`, COUNT(*) AS `C`\n" + "FROM `foodmart`.`product`\n" + "GROUP BY `product_class_id` WITH ROLLUP\n" + "ORDER BY `product_class_id` IS NULL, `product_class_id`," + " COUNT(*) IS NULL, COUNT(*)";
    sql(query).ok(expected).withMysql().ok(expectedMySql);
}

