    final String expected = "SELECT \"product_class_id\", \"brand_name\"," + " COUNT(*) AS \"C\"\n" + "FROM \"foodmart\".\"product\"\n" + "GROUP BY ROLLUP(\"product_class_id\", \"brand_name\")\n" + "ORDER BY \"product_class_id\", \"brand_name\", COUNT(*)";
