/**
 * Test case for
 * <a href="https://issues.apache.org/jira/browse/CALCITE-1174">[CALCITE-1174]
 * When generating SQL, translate SUM0(x) to COALESCE(SUM(x), 0)</a>.
 */
@Test
public void testSum0BecomesCoalesce() {
    final RelBuilder builder = relBuilder();
    final RelNode root = builder.scan("EMP").aggregate(builder.groupKey(), builder.aggregateCall(SqlStdOperatorTable.SUM0, builder.field(3)).as("s")).build();
    final String expectedMysql = "SELECT COALESCE(SUM(`MGR`), 0) AS `s`\n" + "FROM `scott`.`EMP`";
    assertThat(toSql(root, SqlDialect.DatabaseProduct.MYSQL.getDialect()), isLinux(expectedMysql));
    final String expectedPostgresql = "SELECT COALESCE(SUM(\"MGR\"), 0) AS \"s\"\n" + "FROM \"scott\".\"EMP\"";
    assertThat(toSql(root, SqlDialect.DatabaseProduct.POSTGRESQL.getDialect()), isLinux(expectedPostgresql));
}

/**
 * As {@link #testSum0BecomesCoalesce()} but for windowed aggregates.
 */
@Test
public void testWindowedSum0BecomesCoalesce() {
    final String query = "select\n" + "  AVG(\"net_weight\") OVER (order by \"product_id\" rows 3 preceding)\n" + "from \"foodmart\".\"product\"";
    final String expectedPostgresql = "SELECT CASE WHEN (COUNT(\"net_weight\")" + " OVER (ORDER BY \"product_id\" ROWS BETWEEN 3 PRECEDING AND CURRENT ROW)) > 0 " + "THEN COALESCE(SUM(\"net_weight\")" + " OVER (ORDER BY \"product_id\" ROWS BETWEEN 3 PRECEDING AND CURRENT ROW), 0)" + " ELSE NULL END / (COUNT(\"net_weight\")" + " OVER (ORDER BY \"product_id\" ROWS BETWEEN 3 PRECEDING AND CURRENT ROW))\n" + "FROM \"foodmart\".\"product\"";
    sql(query).withPostgresql().ok(expectedPostgresql);
}

