/**
 * Test case for
 * <a href="https://issues.apache.org/jira/browse/CALCITE-1946">[CALCITE-1946]
 * JDBC adapter should generate sub-SELECT if dialect does not support nested
 * aggregate functions</a>.
 */
@Test
public void testNestedAggregates() {
    // PostgreSQL, MySQL, Vertica do not support nested aggregate functions, so
    // for these, the JDBC adapter generates a SELECT in the FROM clause.
    // Oracle can do it in a single SELECT.
    final String query = "select\n" + "    SUM(\"net_weight1\") as \"net_weight_converted\"\n" + "  from (" + "    select\n" + "       SUM(\"net_weight\") as \"net_weight1\"\n" + "    from \"foodmart\".\"product\"\n" + "    group by \"product_id\")";
    final String expectedOracle = "SELECT SUM(SUM(\"net_weight\")) \"net_weight_converted\"\n" + "FROM \"foodmart\".\"product\"\n" + "GROUP BY \"product_id\"";
    final String expectedMySQL = "SELECT SUM(`net_weight1`) AS `net_weight_converted`\n" + "FROM (SELECT SUM(`net_weight`) AS `net_weight1`\n" + "FROM `foodmart`.`product`\n" + "GROUP BY `product_id`) AS `t1`";
    final String expectedVertica = "SELECT SUM(\"net_weight1\") AS \"net_weight_converted\"\n" + "FROM (SELECT SUM(\"net_weight\") AS \"net_weight1\"\n" + "FROM \"foodmart\".\"product\"\n" + "GROUP BY \"product_id\") AS \"t1\"";
    final String expectedPostgresql = "SELECT SUM(\"net_weight1\") AS \"net_weight_converted\"\n" + "FROM (SELECT SUM(\"net_weight\") AS \"net_weight1\"\n" + "FROM \"foodmart\".\"product\"\n" + "GROUP BY \"product_id\") AS \"t1\"";
    sql(query).withOracle().ok(expectedOracle).withMysql().ok(expectedMySQL).withVertica().ok(expectedVertica).withPostgresql().ok(expectedPostgresql);
}

