 * <a href="https://issues.apache.org/jira/browse/CALCITE-1372">[CALCITE-1372]
 * JDBC adapter generates SQL with wrong field names</a>.
 */
@Test
public void testJoinPlan2() {
    final String sql = "SELECT v1.deptno, v2.deptno\n" + "FROM dept v1 LEFT JOIN emp v2 ON v1.deptno = v2.deptno\n" + "WHERE v2.job LIKE 'PRESIDENT'";
    final String expected = "SELECT \"DEPT\".\"DEPTNO\"," + " \"EMP\".\"DEPTNO\" AS \"DEPTNO0\"\n" + "FROM \"SCOTT\".\"DEPT\"\n" + "LEFT JOIN \"SCOTT\".\"EMP\"" + " ON \"DEPT\".\"DEPTNO\" = \"EMP\".\"DEPTNO\"\n" + "WHERE \"EMP\".\"JOB\" LIKE 'PRESIDENT'";
    // DB2 does not have implicit aliases, so generates explicit "AS DEPT"
    // and "AS EMP"
    final String expectedDb2 = "SELECT DEPT.DEPTNO, EMP.DEPTNO AS DEPTNO0\n" + "FROM SCOTT.DEPT AS DEPT\n" + "LEFT JOIN SCOTT.EMP AS EMP ON DEPT.DEPTNO = EMP.DEPTNO\n" + "WHERE EMP.JOB LIKE 'PRESIDENT'";
    sql(sql).schema(CalciteAssert.SchemaSpec.JDBC_SCOTT).ok(expected).withDb2().ok(expectedDb2);
}

