    // Some of the "IS NULL" and "IS NOT NULL" are reduced to TRUE or FALSE,
    // but not all.
    String expected = "SELECT *\nFROM \"foodmart\".\"sales_fact_1997\"\n" + "INNER JOIN \"foodmart\".\"customer\" " + "ON \"sales_fact_1997\".\"customer_id\" = \"customer\".\"customer_id\"" + " OR FALSE AND FALSE" + " OR \"customer\".\"occupation\" IS NULL\n" + "INNER JOIN \"foodmart\".\"product\" " + "ON \"sales_fact_1997\".\"product_id\" = \"product\".\"product_id\"" + " OR TRUE" + " OR TRUE";
