    sql(queryDatePlus).withDb2().ok(expectedDatePlus);
    String queryDateMinus = "select  * from \"employee\" where  \"hire_date\" - " + "INTERVAL '19800' SECOND(5) > TIMESTAMP '2005-10-17 00:00:00' ";
