/**
 * Test case for
 * <a href="https://issues.apache.org/jira/browse/CALCITE-1826">[CALCITE-1826]
 * JDBC dialect-specific FLOOR fails when in GROUP BY</a>.
 */
@Test
public void testFloorWithGroupBy() {
    final String query = "SELECT floor(\"hire_date\" TO MINUTE)\n" + "FROM \"employee\"\n" + "GROUP BY floor(\"hire_date\" TO MINUTE)";
    final String expected = "SELECT TRUNC(hire_date, 'MI')\n" + "FROM foodmart.employee\n" + "GROUP BY TRUNC(hire_date, 'MI')";
    final String expectedOracle = "SELECT TRUNC(\"hire_date\", 'MINUTE')\n" + "FROM \"foodmart\".\"employee\"\n" + "GROUP BY TRUNC(\"hire_date\", 'MINUTE')";
    final String expectedPostgresql = "SELECT DATE_TRUNC('MINUTE', \"hire_date\")\n" + "FROM \"foodmart\".\"employee\"\n" + "GROUP BY DATE_TRUNC('MINUTE', \"hire_date\")";
    final String expectedMysql = "SELECT" + " DATE_FORMAT(`hire_date`, '%Y-%m-%d %H:%i:00')\n" + "FROM `foodmart`.`employee`\n" + "GROUP BY DATE_FORMAT(`hire_date`, '%Y-%m-%d %H:%i:00')";
    sql(query).withHsqldb().ok(expected).withOracle().ok(expectedOracle).withPostgresql().ok(expectedPostgresql).withMysql().ok(expectedMysql);
}

@Test
public void testSubstring() {
    final String query = "select substring(\"brand_name\" from 2) " + "from \"product\"\n";
    final String expectedOracle = "SELECT SUBSTR(\"brand_name\", 2)\n" + "FROM \"foodmart\".\"product\"";
    final String expectedPostgresql = "SELECT SUBSTRING(\"brand_name\" FROM 2)\n" + "FROM \"foodmart\".\"product\"";
    final String expectedMysql = "SELECT SUBSTRING(`brand_name` FROM 2)\n" + "FROM `foodmart`.`product`";
    sql(query).withOracle().ok(expectedOracle).withPostgresql().ok(expectedPostgresql).withMysql().ok(expectedMysql).withMssql().// mssql does not support this syntax and so should fail
    throws_("MSSQL SUBSTRING requires FROM and FOR arguments");
}

@Test
public void testSubstringWithFor() {
    final String query = "select substring(\"brand_name\" from 2 for 3) " + "from \"product\"\n";
    final String expectedOracle = "SELECT SUBSTR(\"brand_name\", 2, 3)\n" + "FROM \"foodmart\".\"product\"";
    final String expectedPostgresql = "SELECT SUBSTRING(\"brand_name\" FROM 2 FOR 3)\n" + "FROM \"foodmart\".\"product\"";
    final String expectedMysql = "SELECT SUBSTRING(`brand_name` FROM 2 FOR 3)\n" + "FROM `foodmart`.`product`";
    final String expectedMssql = "SELECT SUBSTRING([brand_name], 2, 3)\n" + "FROM [foodmart].[product]";
    sql(query).withOracle().ok(expectedOracle).withPostgresql().ok(expectedPostgresql).withMysql().ok(expectedMysql).withMssql().ok(expectedMssql);
}

