@Test
public void testExtractRewriteForInvalidMonthComparison() {
    // "EXTRACT(MONTH FROM ts) = 14" will never be TRUE
    final Fixture2 f = new Fixture2();
    checkDateRange(f, f.and(f.eq(f.exYearTs, f.literal(2010)), f.eq(f.exMonthTs, f.literal(14))), is("AND(AND(>=($9, 2010-01-01 00:00:00), <($9, 2011-01-01 00:00:00))," + " false)"));
    // "EXTRACT(MONTH FROM ts) = 0" will never be TRUE
    checkDateRange(f, f.and(f.eq(f.exYearTs, f.literal(2010)), f.eq(f.exMonthTs, f.literal(0))), is("AND(AND(>=($9, 2010-01-01 00:00:00), <($9, 2011-01-01 00:00:00))," + " false)"));
    // "EXTRACT(MONTH FROM ts) = 13" will never be TRUE
    checkDateRange(f, f.and(f.eq(f.exYearTs, f.literal(2010)), f.eq(f.exMonthTs, f.literal(13))), is("AND(AND(>=($9, 2010-01-01 00:00:00), <($9, 2011-01-01 00:00:00))," + " false)"));
    // "EXTRACT(MONTH FROM ts) = 12" might be TRUE
    // Careful with boundaries, because Calendar.DECEMBER = 11
    checkDateRange(f, f.and(f.eq(f.exYearTs, f.literal(2010)), f.eq(f.exMonthTs, f.literal(12))), is("AND(AND(>=($9, 2010-01-01 00:00:00), <($9, 2011-01-01 00:00:00))," + " AND(>=($9, 2010-12-01 00:00:00), <($9, 2011-01-01 00:00:00)))"));
    // "EXTRACT(MONTH FROM ts) = 1" can happen
    // Careful with boundaries, because Calendar.JANUARY = 0
    checkDateRange(f, f.and(f.eq(f.exYearTs, f.literal(2010)), f.eq(f.exMonthTs, f.literal(1))), is("AND(AND(>=($9, 2010-01-01 00:00:00), <($9, 2011-01-01 00:00:00))," + " AND(>=($9, 2010-01-01 00:00:00), <($9, 2010-02-01 00:00:00)))"));
}

