/**
 * Tests {@link RexCopier#visitOver(RexOver)}
 */
@Test
public void testCopyOver() {
    final RelDataTypeFactory sourceTypeFactory = new SqlTypeFactoryImpl(RelDataTypeSystem.DEFAULT);
    RelDataType type = sourceTypeFactory.createSqlType(SqlTypeName.VARCHAR, 65536);
    final RelDataTypeFactory targetTypeFactory = new MySqlTypeFactoryImpl(RelDataTypeSystem.DEFAULT);
    final RexBuilder builder = new RexBuilder(targetTypeFactory);
    final RexOver node = (RexOver) builder.makeOver(type, SqlStdOperatorTable.COUNT, ImmutableList.of(builder.makeInputRef(type, 0)), ImmutableList.of(builder.makeInputRef(type, 1)), ImmutableList.of(new RexFieldCollation(builder.makeInputRef(type, 2), ImmutableSet.of())), RexWindowBound.create(SqlWindow.createUnboundedPreceding(SqlParserPos.ZERO), null), RexWindowBound.create(SqlWindow.createCurrentRow(SqlParserPos.ZERO), null), true, true, false, false, false);
    final RexNode copy = builder.copy(node);
    assertTrue(copy instanceof RexOver);
    RexOver result = (RexOver) copy;
    assertThat(result.getType().getSqlTypeName(), is(SqlTypeName.VARCHAR));
    assertThat(result.getType().getPrecision(), is(PRECISION));
    assertThat(result.getWindow(), is(node.getWindow()));
    assertThat(result.getAggOperator(), is(node.getAggOperator()));
    assertThat(result.getAggOperator(), is(node.getAggOperator()));
    assertEquals(node.isDistinct(), result.isDistinct());
    assertEquals(node.ignoreNulls(), result.ignoreNulls());
    for (int i = 0; i < node.getOperands().size(); i++) {
        assertThat(result.getOperands().get(i).getType().getSqlTypeName(), is(node.getOperands().get(i).getType().getSqlTypeName()));
        assertThat(result.getOperands().get(i).getType().getPrecision(), is(PRECISION));
    }
}

