@Test
public void testBetween() {
    check("select * from t where price between 1 and 2", "SELECT *\n" + "FROM `T`\n" + "WHERE (`PRICE` BETWEEN ASYMMETRIC 1 AND 2)");
    check("select * from t where price between symmetric 1 and 2", "SELECT *\n" + "FROM `T`\n" + "WHERE (`PRICE` BETWEEN SYMMETRIC 1 AND 2)");
    check("select * from t where price not between symmetric 1 and 2", "SELECT *\n" + "FROM `T`\n" + "WHERE (`PRICE` NOT BETWEEN SYMMETRIC 1 AND 2)");
    check("select * from t where price between ASYMMETRIC 1 and 2+2*2", "SELECT *\n" + "FROM `T`\n" + "WHERE (`PRICE` BETWEEN ASYMMETRIC 1 AND (2 + (2 * 2)))");
    check("select * from t where price > 5 and price not between 1 + 2 and 3 * 4 AnD price is null", "SELECT *\n" + "FROM `T`\n" + "WHERE (((`PRICE` > 5) AND (`PRICE` NOT BETWEEN ASYMMETRIC (1 + 2) AND (3 * 4))) AND (`PRICE` IS NULL))");
    check("select * from t where price > 5 and price between 1 + 2 and 3 * 4 + price is null", "SELECT *\n" + "FROM `T`\n" + "WHERE ((`PRICE` > 5) AND ((`PRICE` BETWEEN ASYMMETRIC (1 + 2) AND ((3 * 4) + `PRICE`)) IS NULL))");
    check("select * from t where price > 5 and price between 1 + 2 and 3 * 4 or price is null", "SELECT *\n" + "FROM `T`\n" + "WHERE (((`PRICE` > 5) AND (`PRICE` BETWEEN ASYMMETRIC (1 + 2) AND (3 * 4))) OR (`PRICE` IS NULL))");
    check("values a between c and d and e and f between g and h", "VALUES (ROW((((`A` BETWEEN ASYMMETRIC `C` AND `D`) AND `E`) AND (`F` BETWEEN ASYMMETRIC `G` AND `H`))))");
    checkFails("values a between b or c^", ".*BETWEEN operator has no terminating AND");
    checkFails("values a ^between^", "(?s).*Encountered \"between <EOF>\" at line 1, column 10.*");
    checkFails("values a between symmetric 1^", ".*BETWEEN operator has no terminating AND");
    // precedence of BETWEEN is higher than AND and OR, but lower than '+'
    check("values a between b and c + 2 or d and e", "VALUES (ROW(((`A` BETWEEN ASYMMETRIC `B` AND (`C` + 2)) OR (`D` AND `E`))))");
    // '=' has slightly lower precedence than BETWEEN; both are left-assoc
    check("values x = a between b and c = d = e", "VALUES (ROW((((`X` = (`A` BETWEEN ASYMMETRIC `B` AND `C`)) = `D`) = `E`)))");
    // AND doesn't match BETWEEN if it's between parentheses!
    check("values a between b or (c and d) or e and f", "VALUES (ROW((`A` BETWEEN ASYMMETRIC ((`B` OR (`C` AND `D`)) OR `E`) AND `F`)))");
}

