/**
 * Tests MINUS, which is equivalent to EXCEPT but only supported in some
 * conformance levels (e.g. ORACLE).
 */
@Test
public void testSetMinus() {
    final String pattern = "MINUS is not allowed under the current SQL conformance level";
    final String sql = "select col1 from table1 MINUS select col1 from table2";
    sql(sql).fails(pattern);
    conformance = SqlConformanceEnum.ORACLE_10;
    final String expected = "(SELECT `COL1`\n" + "FROM `TABLE1`\n" + "EXCEPT\n" + "SELECT `COL1`\n" + "FROM `TABLE2`)";
    sql(sql).ok(expected);
    final String sql2 = "select col1 from table1 MINUS ALL select col1 from table2";
    final String expected2 = "(SELECT `COL1`\n" + "FROM `TABLE1`\n" + "EXCEPT ALL\n" + "SELECT `COL1`\n" + "FROM `TABLE2`)";
    sql(sql2).ok(expected2);
}

/**
 * MINUS is a <b>reserved</b> keyword in Calcite in all conformances, even
 * in the default conformance, where it is not allowed as an alternative to
 * EXCEPT. (It is reserved in Oracle but not in any version of the SQL
 * standard.)
 */
@Test
public void testMinusIsReserved() {
    sql("select ^minus^ from t").fails("(?s).*Encountered \"minus\" at .*");
    sql("select ^minus^ select").fails("(?s).*Encountered \"minus\" at .*");
    sql("select * from t as ^minus^ where x < y").fails("(?s).*Encountered \"minus\" at .*");
}

