@Test
public void testCaseExpression() {
    // implicit simple "ELSE NULL" case
    checkExp("case \t col1 when 1 then 'one' end", "(CASE WHEN (`COL1` = 1) THEN 'one' ELSE NULL END)");
    // implicit searched "ELSE NULL" case
    checkExp("case when nbr is false then 'one' end", "(CASE WHEN (`NBR` IS FALSE) THEN 'one' ELSE NULL END)");
    // multiple WHENs
    checkExp("case col1 when \n1.2 then 'one' when 2 then 'two' else 'three' end", "(CASE WHEN (`COL1` = 1.2) THEN 'one' WHEN (`COL1` = 2) THEN 'two' ELSE 'three' END)");
    // sub-queries as case expression operands
    checkExp("case (select * from emp) when 1 then 2 end", "(CASE WHEN ((SELECT *\n" + "FROM `EMP`) = 1) THEN 2 ELSE NULL END)");
    checkExp("case 1 when (select * from emp) then 2 end", "(CASE WHEN (1 = (SELECT *\n" + "FROM `EMP`)) THEN 2 ELSE NULL END)");
    checkExp("case 1 when 2 then (select * from emp) end", "(CASE WHEN (1 = 2) THEN (SELECT *\n" + "FROM `EMP`) ELSE NULL END)");
    checkExp("case 1 when 2 then 3 else (select * from emp) end", "(CASE WHEN (1 = 2) THEN 3 ELSE (SELECT *\n" + "FROM `EMP`) END)");
    checkExp("case x when 2, 4 then 3 else 4 end", "(CASE WHEN (`X` IN (2, 4)) THEN 3 ELSE 4 END)");
    // comma-list must not be empty
    checkFails("case x when 2, 4 then 3 when ^then^ 5 else 4 end", "(?s)Encountered \"then\" at .*");
    // commas not allowed in boolean case
    checkFails("case when b1, b2 ^when^ 2, 4 then 3 else 4 end", "(?s)Encountered \"when\" at .*");
}

