@Test
public void testAs() {
    // AS is optional for column aliases
    check("select x y from t", "SELECT `X` AS `Y`\n" + "FROM `T`");
    check("select x AS y from t", "SELECT `X` AS `Y`\n" + "FROM `T`");
    check("select sum(x) y from t group by z", "SELECT SUM(`X`) AS `Y`\n" + "FROM `T`\n" + "GROUP BY `Z`");
    // Even after OVER
    check("select count(z) over w foo from Bids window w as (order by x)", "SELECT (COUNT(`Z`) OVER `W`) AS `FOO`\n" + "FROM `BIDS`\n" + "WINDOW `W` AS (ORDER BY `X`)");
    // AS is optional for table correlation names
    final String expected = "SELECT `X`\n" + "FROM `T` AS `T1`";
    check("select x from t as t1", expected);
    check("select x from t t1", expected);
    // AS is required in WINDOW declaration
    checkFails("select sum(x) over w from bids window w ^(order by x)", "(?s).*Encountered \"\\(\".*");
    // Error if OVER and AS are in wrong order
    checkFails("select count(*) as foo ^over^ w from Bids window w (order by x)", "(?s).*Encountered \"over\".*");
}

