@Test
public void testTimestampAddAndDiff() {
    Map<String, List<String>> tsi = ImmutableMap.<String, List<String>>builder().put("MICROSECOND", Arrays.asList("FRAC_SECOND", "MICROSECOND", "SQL_TSI_MICROSECOND")).put("NANOSECOND", Arrays.asList("NANOSECOND", "SQL_TSI_FRAC_SECOND")).put("SECOND", Arrays.asList("SECOND", "SQL_TSI_SECOND")).put("MINUTE", Arrays.asList("MINUTE", "SQL_TSI_MINUTE")).put("HOUR", Arrays.asList("HOUR", "SQL_TSI_HOUR")).put("DAY", Arrays.asList("DAY", "SQL_TSI_DAY")).put("WEEK", Arrays.asList("WEEK", "SQL_TSI_WEEK")).put("MONTH", Arrays.asList("MONTH", "SQL_TSI_MONTH")).put("QUARTER", Arrays.asList("QUARTER", "SQL_TSI_QUARTER")).put("YEAR", Arrays.asList("YEAR", "SQL_TSI_YEAR")).build();
    List<String> functions = ImmutableList.<String>builder().add("timestampadd(%1$s, 12, %2$scurrent_timestamp%2$s)").add("timestampdiff(%1$s, %2$scurrent_timestamp%2$s, %2$scurrent_timestamp%2$s)").build();
    for (Map.Entry<String, List<String>> intervalGroup : tsi.entrySet()) {
        for (String function : functions) {
            for (String interval : intervalGroup.getValue()) {
                checkExp(String.format(Locale.ROOT, function, interval, ""), String.format(Locale.ROOT, function, intervalGroup.getKey(), "`").toUpperCase(Locale.ROOT));
            }
        }
    }
    checkExpFails("timestampadd(^incorrect^, 1, current_timestamp)", "(?s).*Was expecting one of.*");
    checkExpFails("timestampdiff(^incorrect^, current_timestamp, current_timestamp)", "(?s).*Was expecting one of.*");
}

