/**
 * Tests that reserved keywords are not added to the parser unintentionally.
 * (Most keywords are non-reserved. The set of reserved words generally
 * only changes with a new version of the SQL standard.)
 *
 * <p>If the new keyword added is intended to be a reserved keyword, update
 * the {@link #RESERVED_KEYWORDS} list. If not, add the keyword to the
 * non-reserved keyword list in the parser.
 */
@Test
public void testNoUnintendedNewReservedKeywords() {
    assumeTrue("don't run this test for sub-classes", isNotSubclass());
    final SqlAbstractParserImpl.Metadata metadata = getSqlParser("").getMetadata();
    final SortedSet<String> reservedKeywords = new TreeSet<>();
    final SortedSet<String> keywords92 = keywords("92");
    for (String s : metadata.getTokens()) {
        if (metadata.isKeyword(s) && metadata.isReservedWord(s)) {
            reservedKeywords.add(s);
        }
        if (false) {
            // Cannot enable this test yet, because the parser's list of SQL:92
            // reserved words is not consistent with keywords("92").
            assertThat(s, metadata.isSql92ReservedWord(s), is(keywords92.contains(s)));
        }
    }
    final String reason = "The parser has at least one new reserved keyword. " + "Are you sure it should be reserved? Difference:\n" + DiffTestCase.diffLines(ImmutableList.copyOf(getReservedKeywords()), ImmutableList.copyOf(reservedKeywords));
    assertThat(reason, reservedKeywords, is(getReservedKeywords()));
}

/**
 * Generates a copy of {@code reference.md} with the current set of key
 * words. Fails if the copy is different from the original.
 */
@Test
public void testGenerateKeyWords() throws IOException {
    assumeTrue("don't run this test for sub-classes", isNotSubclass());
    // inUrl = "file:/home/x/calcite/core/target/test-classes/hsqldb-model.json"
    String path = "hsqldb-model.json";
    File hsqlDbModel = Sources.of(SqlParserTest.class.getResource("/" + path)).file();
    assert hsqlDbModel.getAbsolutePath().endsWith(Paths.get("core", "target", "test-classes", "hsqldb-model.json").toString()) : hsqlDbModel.getAbsolutePath() + " should end with core/target/test-classes/hsqldb-model.json";
    // skip hsqldb-model.json, test-classes, target, core
    // The assertion above protects us from walking over unrelated paths
    final File base = hsqlDbModel.getAbsoluteFile().getParentFile().getParentFile().getParentFile().getParentFile();
    final File inFile = new File(base, "site/_docs/reference.md");
    final File outFile = new File(base, "core/target/surefire/reference.md");
    outFile.getParentFile().mkdirs();
    try (BufferedReader r = Util.reader(inFile);
        FileOutputStream fos = new FileOutputStream(outFile);
        PrintWriter w = Util.printWriter(outFile)) {
        String line;
        int stage = 0;
        while ((line = r.readLine()) != null) {
            if (line.equals("{% comment %} end {% endcomment %}")) {
                ++stage;
            }
            if (stage != 1) {
                w.println(line);
            }
            if (line.equals("{% comment %} start {% endcomment %}")) {
                ++stage;
                SqlAbstractParserImpl.Metadata metadata = getSqlParser("").getMetadata();
                int z = 0;
                for (String s : metadata.getTokens()) {
                    if (z++ > 0) {
                        w.println(",");
                    }
                    if (metadata.isKeyword(s)) {
                        w.print(metadata.isReservedWord(s) ? ("**" + s + "**") : s);
                    }
                }
                w.println(".");
            }
        }
        w.flush();
        fos.flush();
        fos.getFD().sync();
    }
    String diff = DiffTestCase.diff(outFile, inFile);
    if (!diff.isEmpty()) {
        throw new AssertionError("Mismatch between " + outFile + " and " + inFile + ":\n" + diff);
    }
}

