@Test
public void testCastApproxNumericLimits() {
    tester.setFor(SqlStdOperatorTable.CAST);
    // Test casting for min,max, out of range for approx numeric types
    for (int i = 0; i < NUMERIC_TYPE_NAMES.length; i++) {
        String type = NUMERIC_TYPE_NAMES[i];
        boolean isFloat;
        if (type.equalsIgnoreCase("DOUBLE") || type.equalsIgnoreCase("FLOAT")) {
            isFloat = false;
        } else if (type.equalsIgnoreCase("REAL")) {
            isFloat = true;
        } else {
            // Skip non-approx types
            continue;
        }
        if (!enable) {
            return;
        }
        // Convert from literal to type
        checkCastToApproxOkay(MAX_NUMERIC_STRINGS[i], type, Double.parseDouble(MAX_NUMERIC_STRINGS[i]), isFloat ? 1E32 : 0);
        checkCastToApproxOkay(MIN_NUMERIC_STRINGS[i], type, Double.parseDouble(MIN_NUMERIC_STRINGS[i]), 0);
        if (isFloat) {
            checkCastFails(MAX_OVERFLOW_NUMERIC_STRINGS[i], type, OUT_OF_RANGE_MESSAGE, true);
        } else {
            // Double: Literal out of range
            checkCastFails(MAX_OVERFLOW_NUMERIC_STRINGS[i], type, LITERAL_OUT_OF_RANGE_MESSAGE, false);
        }
        // Underflow: goes to 0
        checkCastToApproxOkay(MIN_OVERFLOW_NUMERIC_STRINGS[i], type, 0, 0);
        // Convert from string to type
        checkCastToApproxOkay("'" + MAX_NUMERIC_STRINGS[i] + "'", type, Double.parseDouble(MAX_NUMERIC_STRINGS[i]), isFloat ? 1E32 : 0);
        checkCastToApproxOkay("'" + MIN_NUMERIC_STRINGS[i] + "'", type, Double.parseDouble(MIN_NUMERIC_STRINGS[i]), 0);
        checkCastFails("'" + MAX_OVERFLOW_NUMERIC_STRINGS[i] + "'", type, OUT_OF_RANGE_MESSAGE, true);
        // Underflow: goes to 0
        checkCastToApproxOkay("'" + MIN_OVERFLOW_NUMERIC_STRINGS[i] + "'", type, 0, 0);
        // Convert from type to string
        // Treated as DOUBLE
        checkCastToString(MAX_NUMERIC_STRINGS[i], null, isFloat ? null : "1.79769313486231E308");
        // TODO: The following tests are slightly different depending on
        // whether the java or fennel calc are used.
        // Try to make them the same
        if (false) /* fennel calc*/
        {
            // Treated as FLOAT or DOUBLE
            checkCastToString(MAX_NUMERIC_STRINGS[i], type, // Treated as DOUBLE
            isFloat ? "3.402824E38" : "1.797693134862316E308");
            checkCastToString(MIN_NUMERIC_STRINGS[i], null, // Treated as FLOAT or DOUBLE
            isFloat ? null : "4.940656458412465E-324");
            checkCastToString(MIN_NUMERIC_STRINGS[i], type, isFloat ? "1.401299E-45" : "4.940656458412465E-324");
        } else if (false) /* JavaCalc */
        {
            // Treated as FLOAT or DOUBLE
            checkCastToString(MAX_NUMERIC_STRINGS[i], type, // Treated as DOUBLE
            isFloat ? "3.402823E38" : "1.797693134862316E308");
            checkCastToString(MIN_NUMERIC_STRINGS[i], null, // Treated as FLOAT or DOUBLE
            isFloat ? null : null);
            checkCastToString(MIN_NUMERIC_STRINGS[i], type, isFloat ? "1.401298E-45" : null);
        }
        checkCastFails("'notnumeric'", type, INVALID_CHAR_MESSAGE, true);
    }
}

