    tester.checkScalar("cast('  12:42:25  ' as TIME)", "12:42:25", "TIME(0) NOT NULL");
    tester.checkScalar("cast('12:42:25.34' as TIME)", "12:42:25", "TIME(0) NOT NULL");
    if (Bug.FRG282_FIXED) {
        tester.checkScalar("cast('12:42:25.34' as TIME(2))", "12:42:25.34", "TIME(2) NOT NULL");
    }
    tester.checkFails("cast('nottime' as TIME)", BAD_DATETIME_MESSAGE, true);
    if (Bug.CALCITE_2539_FIXED) {
        tester.checkFails("cast('1241241' as TIME)", BAD_DATETIME_MESSAGE, true);
        tester.checkFails("cast('12:54:78' as TIME)", BAD_DATETIME_MESSAGE, true);
        tester.checkFails("cast('12:34:5' as TIME)", BAD_DATETIME_MESSAGE, true);
        tester.checkFails("cast('12:3:45' as TIME)", BAD_DATETIME_MESSAGE, true);
        tester.checkFails("cast('1:23:45' as TIME)", BAD_DATETIME_MESSAGE, true);
    }
    // timestamp <-> string
    checkCastToString("TIMESTAMP '1945-02-24 12:42:25'", null, "1945-02-24 12:42:25");
    if (TODO) {
        // TODO: casting allows one to discard precision without error
        checkCastToString("TIMESTAMP '1945-02-24 12:42:25.34'", null, "1945-02-24 12:42:25.34");
    }
    tester.checkScalar("cast('1945-02-24 12:42:25' as TIMESTAMP)", "1945-02-24 12:42:25", "TIMESTAMP(0) NOT NULL");
    tester.checkScalar("cast('1945-2-2 12:2:5' as TIMESTAMP)", "1945-02-02 12:02:05", "TIMESTAMP(0) NOT NULL");
    tester.checkScalar("cast('  1945-02-24 12:42:25  ' as TIMESTAMP)", "1945-02-24 12:42:25", "TIMESTAMP(0) NOT NULL");
    tester.checkScalar("cast('1945-02-24 12:42:25.34' as TIMESTAMP)", "1945-02-24 12:42:25", "TIMESTAMP(0) NOT NULL");
    tester.checkScalar("cast('1945-12-31' as TIMESTAMP)", "1945-12-31 00:00:00", "TIMESTAMP(0) NOT NULL");
    tester.checkScalar("cast('2004-02-29' as TIMESTAMP)", "2004-02-29 00:00:00", "TIMESTAMP(0) NOT NULL");
    if (Bug.FRG282_FIXED) {
        tester.checkScalar("cast('1945-02-24 12:42:25.34' as TIMESTAMP(2))", "1945-02-24 12:42:25.34", "TIMESTAMP(2) NOT NULL");
    }
    tester.checkFails("cast('nottime' as TIMESTAMP)", BAD_DATETIME_MESSAGE, true);
    if (Bug.CALCITE_2539_FIXED) {
        tester.checkFails("cast('1241241' as TIMESTAMP)", BAD_DATETIME_MESSAGE, true);
        tester.checkFails("cast('1945-20-24 12:42:25.34' as TIMESTAMP)", BAD_DATETIME_MESSAGE, true);
        tester.checkFails("cast('1945-01-24 25:42:25.34' as TIMESTAMP)", BAD_DATETIME_MESSAGE, true);
        tester.checkFails("cast('1945-1-24 12:23:34.454' as TIMESTAMP)", BAD_DATETIME_MESSAGE, true);
    }
    // date <-> string
    checkCastToString("DATE '1945-02-24'", null, "1945-02-24");
    checkCastToString("DATE '1945-2-24'", null, "1945-02-24");
    tester.checkScalar("cast('1945-02-24' as DATE)", "1945-02-24", "DATE NOT NULL");
    tester.checkScalar("cast(' 1945-2-4 ' as DATE)", "1945-02-04", "DATE NOT NULL");
    tester.checkScalar("cast('  1945-02-24  ' as DATE)", "1945-02-24", "DATE NOT NULL");
    tester.checkFails("cast('notdate' as DATE)", BAD_DATETIME_MESSAGE, true);
    if (Bug.CALCITE_2539_FIXED) {
        tester.checkFails("cast('52534253' as DATE)", BAD_DATETIME_MESSAGE, true);
        tester.checkFails("cast('1945-30-24' as DATE)", BAD_DATETIME_MESSAGE, true);
    }
    // cast null
    tester.checkNull("cast(null as date)");
    tester.checkNull("cast(null as timestamp)");
    tester.checkNull("cast(null as time)");
    tester.checkNull("cast(cast(null as varchar(10)) as time)");
    tester.checkNull("cast(cast(null as varchar(10)) as date)");
    tester.checkNull("cast(cast(null as varchar(10)) as timestamp)");
    tester.checkNull("cast(cast(null as date) as timestamp)");
    tester.checkNull("cast(cast(null as time) as timestamp)");
    tester.checkNull("cast(cast(null as timestamp) as date)");
    tester.checkNull("cast(cast(null as timestamp) as time)");
}

