@Test
public void testJsonValue() {
    // type casting test
    tester.checkString("json_value('{\"foo\":100}', 'strict $.foo')", "100", "VARCHAR(2000)");
    tester.checkScalar("json_value('{\"foo\":100}', 'strict $.foo' returning integer)", 100, "INTEGER");
    tester.checkFails("json_value('{\"foo\":\"100\"}', 'strict $.foo' returning boolean)", INVALID_CHAR_MESSAGE, true);
    tester.checkScalar("json_value('{\"foo\":100}', 'lax $.foo1' returning integer " + "null on empty)", null, "INTEGER");
    tester.checkScalar("json_value('{\"foo\":\"100\"}', 'strict $.foo1' returning boolean " + "null on error)", null, "BOOLEAN");
    // lax test
    tester.checkString("json_value('{\"foo\":100}', 'lax $.foo' null on empty)", "100", "VARCHAR(2000)");
    tester.checkString("json_value('{\"foo\":100}', 'lax $.foo' error on empty)", "100", "VARCHAR(2000)");
    tester.checkString("json_value('{\"foo\":100}', 'lax $.foo' default 'empty' on empty)", "100", "VARCHAR(2000)");
    tester.checkString("json_value('{\"foo\":100}', 'lax $.foo1' null on empty)", null, "VARCHAR(2000)");
    tester.checkFails("json_value('{\"foo\":100}', 'lax $.foo1' error on empty)", "(?s).*Empty result of JSON_VALUE function is not allowed.*", true);
    tester.checkString("json_value('{\"foo\":100}', 'lax $.foo1' default 'empty' on empty)", "empty", "VARCHAR(2000)");
    tester.checkString("json_value('{\"foo\":{}}', 'lax $.foo' null on empty)", null, "VARCHAR(2000)");
    tester.checkFails("json_value('{\"foo\":{}}', 'lax $.foo' error on empty)", "(?s).*Empty result of JSON_VALUE function is not allowed.*", true);
    tester.checkString("json_value('{\"foo\":{}}', 'lax $.foo' default 'empty' on empty)", "empty", "VARCHAR(2000)");
    tester.checkString("json_value('{\"foo\":100}', 'lax $.foo' null on error)", "100", "VARCHAR(2000)");
    tester.checkString("json_value('{\"foo\":100}', 'lax $.foo' error on error)", "100", "VARCHAR(2000)");
    tester.checkString("json_value('{\"foo\":100}', 'lax $.foo' default 'empty' on error)", "100", "VARCHAR(2000)");
    // path error test
    tester.checkString("json_value('{\"foo\":100}', 'invalid $.foo' null on error)", null, "VARCHAR(2000)");
    tester.checkFails("json_value('{\"foo\":100}', 'invalid $.foo' error on error)", "(?s).*Illegal jsonpath spec.*", true);
    tester.checkString("json_value('{\"foo\":100}', " + "'invalid $.foo' default 'empty' on error)", "empty", "VARCHAR(2000)");
    // strict test
    tester.checkString("json_value('{\"foo\":100}', 'strict $.foo' null on empty)", "100", "VARCHAR(2000)");
    tester.checkString("json_value('{\"foo\":100}', 'strict $.foo' error on empty)", "100", "VARCHAR(2000)");
    tester.checkString("json_value('{\"foo\":100}', " + "'strict $.foo' default 'empty' on empty)", "100", "VARCHAR(2000)");
    tester.checkString("json_value('{\"foo\":100}', 'strict $.foo1' null on error)", null, "VARCHAR(2000)");
    tester.checkFails("json_value('{\"foo\":100}', 'strict $.foo1' error on error)", "(?s).*No results for path: \\$\\['foo1'\\].*", true);
    tester.checkString("json_value('{\"foo\":100}', " + "'strict $.foo1' default 'empty' on error)", "empty", "VARCHAR(2000)");
    tester.checkString("json_value('{\"foo\":{}}', 'strict $.foo' null on error)", null, "VARCHAR(2000)");
    tester.checkFails("json_value('{\"foo\":{}}', 'strict $.foo' error on error)", "(?s).*Strict jsonpath mode requires scalar value, " + "and the actual value is: '\\{\\}'.*", true);
    tester.checkString("json_value('{\"foo\":{}}', " + "'strict $.foo' default 'empty' on error)", "empty", "VARCHAR(2000)");
}

@Test
public void testJsonQuery() {
    // lax test
    tester.checkString("json_query('{\"foo\":100}', 'lax $' null on empty)", "{\"foo\":100}", "VARCHAR(2000)");
    tester.checkString("json_query('{\"foo\":100}', 'lax $' error on empty)", "{\"foo\":100}", "VARCHAR(2000)");
    tester.checkString("json_query('{\"foo\":100}', 'lax $' empty array on empty)", "{\"foo\":100}", "VARCHAR(2000)");
    tester.checkString("json_query('{\"foo\":100}', 'lax $' empty object on empty)", "{\"foo\":100}", "VARCHAR(2000)");
    tester.checkString("json_query('{\"foo\":100}', 'lax $.foo' null on empty)", null, "VARCHAR(2000)");
    tester.checkFails("json_query('{\"foo\":100}', 'lax $.foo' error on empty)", "(?s).*Empty result of JSON_QUERY function is not allowed.*", true);
    tester.checkString("json_query('{\"foo\":100}', 'lax $.foo' empty array on empty)", "[]", "VARCHAR(2000)");
    tester.checkString("json_query('{\"foo\":100}', 'lax $.foo' empty object on empty)", "{}", "VARCHAR(2000)");
    // path error test
    tester.checkString("json_query('{\"foo\":100}', 'invalid $.foo' null on error)", null, "VARCHAR(2000)");
    tester.checkFails("json_query('{\"foo\":100}', 'invalid $.foo' error on error)", "(?s).*Illegal jsonpath spec.*", true);
    tester.checkString("json_query('{\"foo\":100}', " + "'invalid $.foo' empty array on error)", "[]", "VARCHAR(2000)");
    tester.checkString("json_query('{\"foo\":100}', " + "'invalid $.foo' empty object on error)", "{}", "VARCHAR(2000)");
    // strict test
    tester.checkString("json_query('{\"foo\":100}', 'strict $' null on empty)", "{\"foo\":100}", "VARCHAR(2000)");
    tester.checkString("json_query('{\"foo\":100}', 'strict $' error on empty)", "{\"foo\":100}", "VARCHAR(2000)");
    tester.checkString("json_query('{\"foo\":100}', 'strict $' empty array on error)", "{\"foo\":100}", "VARCHAR(2000)");
    tester.checkString("json_query('{\"foo\":100}', 'strict $' empty object on error)", "{\"foo\":100}", "VARCHAR(2000)");
    tester.checkString("json_query('{\"foo\":100}', 'strict $.foo1' null on error)", null, "VARCHAR(2000)");
    tester.checkFails("json_query('{\"foo\":100}', 'strict $.foo1' error on error)", "(?s).*No results for path: \\$\\['foo1'\\].*", true);
    tester.checkString("json_query('{\"foo\":100}', 'strict $.foo1' empty array on error)", "[]", "VARCHAR(2000)");
    tester.checkString("json_query('{\"foo\":100}', 'strict $.foo1' empty object on error)", "{}", "VARCHAR(2000)");
    tester.checkString("json_query('{\"foo\":100}', 'strict $.foo' null on error)", null, "VARCHAR(2000)");
    tester.checkFails("json_query('{\"foo\":100}', 'strict $.foo' error on error)", "(?s).*Strict jsonpath mode requires array or object value, " + "and the actual value is: '100'.*", true);
    tester.checkString("json_query('{\"foo\":100}', 'strict $.foo' empty array on error)", "[]", "VARCHAR(2000)");
    tester.checkString("json_query('{\"foo\":100}', 'strict $.foo' empty object on error)", "{}", "VARCHAR(2000)");
    // array wrapper test
    tester.checkString("json_query('{\"foo\":100}', 'strict $.foo' without wrapper)", null, "VARCHAR(2000)");
    tester.checkString("json_query('{\"foo\":100}', 'strict $.foo' without array wrapper)", null, "VARCHAR(2000)");
    tester.checkString("json_query('{\"foo\":100}', 'strict $.foo' with wrapper)", "[100]", "VARCHAR(2000)");
    tester.checkString("json_query('{\"foo\":100}', 'strict $.foo' " + "with unconditional wrapper)", "[100]", "VARCHAR(2000)");
    tester.checkString("json_query('{\"foo\":100}', 'strict $.foo' " + "with conditional wrapper)", "[100]", "VARCHAR(2000)");
    tester.checkString("json_query('{\"foo\":[100]}', 'strict $.foo' without wrapper)", "[100]", "VARCHAR(2000)");
    tester.checkString("json_query('{\"foo\":[100]}', 'strict $.foo' without array wrapper)", "[100]", "VARCHAR(2000)");
    tester.checkString("json_query('{\"foo\":[100]}', 'strict $.foo' with wrapper)", "[[100]]", "VARCHAR(2000)");
    tester.checkString("json_query('{\"foo\":[100]}', 'strict $.foo' " + "with unconditional wrapper)", "[[100]]", "VARCHAR(2000)");
    tester.checkString("json_query('{\"foo\":[100]}', 'strict $.foo' " + "with conditional wrapper)", "[100]", "VARCHAR(2000)");
}

