@Test
public void testSubstringFunction() {
    tester.setFor(SqlStdOperatorTable.SUBSTRING);
    tester.checkString("substring('abc' from 1 for 2)", "ab", "VARCHAR(3) NOT NULL");
    tester.checkString("substring('abc' from 2 for 8)", "bc", "VARCHAR(3) NOT NULL");
    tester.checkString("substring('abc' from 0 for 2)", "a", "VARCHAR(3) NOT NULL");
    tester.checkString("substring('abc' from 0 for 0)", "", "VARCHAR(3) NOT NULL");
