        // substring regexp not supported yet
        tester.checkString("substring('foobar' from '%#\"o_b#\"%' for'#')", "oob", "xx");
    }
    tester.checkNull("substring(cast(null as varchar(1)),1,2)");
}

@Test
public void testTrimFunc() {
    tester.setFor(SqlStdOperatorTable.TRIM);
    // SQL:2003 6.29.11 Trimming a CHAR yields a VARCHAR
    tester.checkString("trim('a' from 'aAa')", "A", "VARCHAR(3) NOT NULL");
    tester.checkString("trim(both 'a' from 'aAa')", "A", "VARCHAR(3) NOT NULL");
    tester.checkString("trim(leading 'a' from 'aAa')", "Aa", "VARCHAR(3) NOT NULL");
    tester.checkString("trim(trailing 'a' from 'aAa')", "aA", "VARCHAR(3) NOT NULL");
    tester.checkNull("trim(cast(null as varchar(1)) from 'a')");
    tester.checkNull("trim('a' from cast(null as varchar(1)))");
    // SQL:2003 6.29.9: trim string must have length=1. Failure occurs
    // at runtime.
    //
    // TODO: Change message to "Invalid argument\(s\) for
    // 'TRIM' function".
    // The message should come from a resource file, and should still
    // have the SQL error code 22027.
    tester.checkFails("trim('xy' from 'abcde')", "Trim error: trim character must be exactly 1 character", true);
    tester.checkFails("trim('' from 'abcde')", "Trim error: trim character must be exactly 1 character", true);
    final SqlTester tester1 = tester.withConformance(SqlConformanceEnum.MYSQL_5);
    tester1.checkString("trim(leading 'eh' from 'hehe__hehe')", "__hehe", "VARCHAR(10) NOT NULL");
    tester1.checkString("trim(trailing 'eh' from 'hehe__hehe')", "hehe__", "VARCHAR(10) NOT NULL");
    tester1.checkString("trim('eh' from 'hehe__hehe')", "__", "VARCHAR(10) NOT NULL");
}

