@Test
public void testExtractIntervalYearMonth() {
    tester.setFor(SqlStdOperatorTable.EXTRACT, VM_FENNEL, VM_JAVA);
    if (TODO) {
        // Not supported, fails in type validation because the extract
        // unit is not YearMonth interval type.
        tester.checkScalar("extract(epoch from interval '4-2' year to month)", // number of seconds elapsed since timestamp
        // '1970-01-01 00:00:00' + input interval
        "131328000", "BIGINT NOT NULL");
        tester.checkScalar("extract(second from interval '4-2' year to month)", "0", "BIGINT NOT NULL");
        tester.checkScalar("extract(millisecond from interval '4-2' year to month)", "0", "BIGINT NOT NULL");
        tester.checkScalar("extract(microsecond from interval '4-2' year to month)", "0", "BIGINT NOT NULL");
        tester.checkScalar("extract(minute from interval '4-2' year to month)", "0", "BIGINT NOT NULL");
        tester.checkScalar("extract(hour from interval '4-2' year to month)", "0", "BIGINT NOT NULL");
        tester.checkScalar("extract(day from interval '4-2' year to month)", "0", "BIGINT NOT NULL");
    }
    // Postgres doesn't support DOW, ISODOW, DOY and WEEK on INTERVAL YEAR MONTH type.
    // SQL standard doesn't have extract units for DOW, ISODOW, DOY and WEEK.
    tester.checkFails("^extract(doy from interval '4-2' year to month)^", INVALID_EXTRACT_UNIT_VALIDATION_ERROR, false);
    tester.checkFails("^extract(dow from interval '4-2' year to month)^", INVALID_EXTRACT_UNIT_VALIDATION_ERROR, false);
    tester.checkFails("^extract(week from interval '4-2' year to month)^", INVALID_EXTRACT_UNIT_VALIDATION_ERROR, false);
    tester.checkFails("^extract(isodow from interval '4-2' year to month)^", INVALID_EXTRACT_UNIT_VALIDATION_ERROR, false);
    tester.checkScalar("extract(month from interval '4-2' year to month)", "2", "BIGINT NOT NULL");
    tester.checkScalar("extract(quarter from interval '4-2' year to month)", "1", "BIGINT NOT NULL");
    tester.checkScalar("extract(year from interval '4-2' year to month)", "4", "BIGINT NOT NULL");
    tester.checkScalar("extract(decade from interval '426-3' year(3) to month)", "42", "BIGINT NOT NULL");
    tester.checkScalar("extract(century from interval '426-3' year(3) to month)", "4", "BIGINT NOT NULL");
    tester.checkScalar("extract(millennium from interval '2005-3' year(4) to month)", "2", "BIGINT NOT NULL");
}

