@Test
public void testTimestampAdd() {
    tester.setFor(SqlStdOperatorTable.TIMESTAMP_ADD);
    tester.checkScalar("timestampadd(MICROSECOND, 2000000, timestamp '2016-02-24 12:42:25')", "2016-02-24 12:42:27", "TIMESTAMP(3) NOT NULL");
    tester.checkScalar("timestampadd(SQL_TSI_SECOND, 2, timestamp '2016-02-24 12:42:25')", "2016-02-24 12:42:27", "TIMESTAMP(0) NOT NULL");
    tester.checkScalar("timestampadd(NANOSECOND, 3000000000, timestamp '2016-02-24 12:42:25')", "2016-02-24 12:42:28", "TIMESTAMP(0) NOT NULL");
    tester.checkScalar("timestampadd(SQL_TSI_FRAC_SECOND, 2000000000, timestamp '2016-02-24 12:42:25')", "2016-02-24 12:42:27", "TIMESTAMP(0) NOT NULL");
    tester.checkScalar("timestampadd(MINUTE, 2, timestamp '2016-02-24 12:42:25')", "2016-02-24 12:44:25", "TIMESTAMP(0) NOT NULL");
    tester.checkScalar("timestampadd(HOUR, -2000, timestamp '2016-02-24 12:42:25')", "2015-12-03 04:42:25", "TIMESTAMP(0) NOT NULL");
    tester.checkNull("timestampadd(HOUR, CAST(NULL AS INTEGER)," + " timestamp '2016-02-24 12:42:25')");
    tester.checkNull("timestampadd(HOUR, -200, CAST(NULL AS TIMESTAMP))");
    tester.checkScalar("timestampadd(MONTH, 3, timestamp '2016-02-24 12:42:25')", "2016-05-24 12:42:25", "TIMESTAMP(0) NOT NULL");
    tester.checkScalar("timestampadd(MONTH, 3, cast(null as timestamp))", null, "TIMESTAMP(0)");
    // TIMESTAMPADD with DATE; returns a TIMESTAMP value for sub-day intervals.
    tester.checkScalar("timestampadd(MONTH, 1, date '2016-06-15')", "2016-07-15", "DATE NOT NULL");
    tester.checkScalar("timestampadd(DAY, 1, date '2016-06-15')", "2016-06-16", "DATE NOT NULL");
    tester.checkScalar("timestampadd(HOUR, -1, date '2016-06-15')", "2016-06-14 23:00:00", "TIMESTAMP(0) NOT NULL");
    tester.checkScalar("timestampadd(MINUTE, 1, date '2016-06-15')", "2016-06-15 00:01:00", "TIMESTAMP(0) NOT NULL");
    tester.checkScalar("timestampadd(SQL_TSI_SECOND, -1, date '2016-06-15')", "2016-06-14 23:59:59", "TIMESTAMP(0) NOT NULL");
    tester.checkScalar("timestampadd(SECOND, 1, date '2016-06-15')", "2016-06-15 00:00:01", "TIMESTAMP(0) NOT NULL");
    tester.checkScalar("timestampadd(SECOND, 1, cast(null as date))", null, "TIMESTAMP(0)");
    tester.checkScalar("timestampadd(DAY, 1, cast(null as date))", null, "DATE");
    // Round to the last day of previous month
    tester.checkScalar("timestampadd(MONTH, 1, date '2016-05-31')", "2016-06-30", "DATE NOT NULL");
    tester.checkScalar("timestampadd(MONTH, 5, date '2016-01-31')", "2016-06-30", "DATE NOT NULL");
    tester.checkScalar("timestampadd(MONTH, -1, date '2016-03-31')", "2016-02-29", "DATE NOT NULL");
    // TIMESTAMPADD with time; returns a time value.The interval is positive.
    tester.checkScalar("timestampadd(SECOND, 1, time '23:59:59')", "00:00:00", "TIME(0) NOT NULL");
    tester.checkScalar("timestampadd(MINUTE, 1, time '00:00:00')", "00:01:00", "TIME(0) NOT NULL");
    tester.checkScalar("timestampadd(MINUTE, 1, time '23:59:59')", "00:00:59", "TIME(0) NOT NULL");
    tester.checkScalar("timestampadd(HOUR, 1, time '23:59:59')", "00:59:59", "TIME(0) NOT NULL");
    tester.checkScalar("timestampadd(DAY, 15, time '23:59:59')", "23:59:59", "TIME(0) NOT NULL");
    tester.checkScalar("timestampadd(WEEK, 3, time '23:59:59')", "23:59:59", "TIME(0) NOT NULL");
    tester.checkScalar("timestampadd(MONTH, 6, time '23:59:59')", "23:59:59", "TIME(0) NOT NULL");
    tester.checkScalar("timestampadd(QUARTER, 1, time '23:59:59')", "23:59:59", "TIME(0) NOT NULL");
    tester.checkScalar("timestampadd(YEAR, 10, time '23:59:59')", "23:59:59", "TIME(0) NOT NULL");
    // TIMESTAMPADD with time; returns a time value .The interval is negative.
    tester.checkScalar("timestampadd(SECOND, -1, time '00:00:00')", "23:59:59", "TIME(0) NOT NULL");
    tester.checkScalar("timestampadd(MINUTE, -1, time '00:00:00')", "23:59:00", "TIME(0) NOT NULL");
    tester.checkScalar("timestampadd(HOUR, -1, time '00:00:00')", "23:00:00", "TIME(0) NOT NULL");
    tester.checkScalar("timestampadd(DAY, -1, time '23:59:59')", "23:59:59", "TIME(0) NOT NULL");
    tester.checkScalar("timestampadd(WEEK, -1, time '23:59:59')", "23:59:59", "TIME(0) NOT NULL");
    tester.checkScalar("timestampadd(MONTH, -1, time '23:59:59')", "23:59:59", "TIME(0) NOT NULL");
    tester.checkScalar("timestampadd(QUARTER, -1, time '23:59:59')", "23:59:59", "TIME(0) NOT NULL");
    tester.checkScalar("timestampadd(YEAR, -1, time '23:59:59')", "23:59:59", "TIME(0) NOT NULL");
}

