        try {
            assertTrue(resultSet.next());
            final BigDecimal bigDecimal = resultSet.getBigDecimal(1);
            assertThat(bigDecimal, equalTo(BigDecimal.valueOf(2008)));
        } catch (SQLException e) {
            throw TestUtil.rethrow(e);
        }
    });
}

