" + "            }
" + "          }
" + "        ]
" + "      ],
" + "      "inputs": []
" + "    }
" + "  ]
" + "}
";
    with.query("explain plan as json for values (1, 'ab', TIMESTAMP '2013-04-02 00:00:00', 0.01)").returns(expectedJson);
