/**
 * Tests an aggregate on a 2-way join query can use an aggregate table.
 */
@Test
public void testLatticeRecognizeGroupJoin() {
    final AtomicInteger counter = new AtomicInteger();
    CalciteAssert.AssertQuery that = foodmartModel().query("select distinct p.\"brand_name\", s.\"customer_id\"\n" + "from \"foodmart\".\"sales_fact_1997\" as s\n" + "join \"foodmart\".\"product\" as p using (\"product_id\")\n").enableMaterializations(true).substitutionMatches(relNode -> {
        counter.incrementAndGet();
        String s = RelOptUtil.toString(relNode);
        assertThat(s, anyOf(containsStringLinux("LogicalProject(brand_name=[$1], customer_id=[$0])\n" + "  LogicalAggregate(group=[{2, 10}])\n" + "    LogicalTableScan(table=[[adhoc, star]])\n"), containsStringLinux("LogicalAggregate(group=[{2, 10}])\n" + "  LogicalTableScan(table=[[adhoc, star]])\n")));
        return null;
    });
    assertThat(counter.intValue(), equalTo(2));
    that.explainContains("" + "EnumerableCalc(expr#0..1=[{inputs}], brand_name=[$t1], customer_id=[$t0])\n" + "  EnumerableTableScan(table=[[adhoc, m{2, 10}]])").returnsCount(69203);
    // Run the same query again and see whether it uses the same
    // materialization.
    that.withHook(Hook.CREATE_MATERIALIZATION, materializationName -> {
        counter.incrementAndGet();
    }).returnsCount(69203);
    // Ideally the counter would stay at 2. It increments to 3 because
    // CalciteAssert.AssertQuery creates a new schema for every request,
    // and therefore cannot re-use lattices or materializations from the
    // previous request.
    assertThat(counter.intValue(), equalTo(3));
}

