 * <a href="https://issues.apache.org/jira/browse/CALCITE-988">[CALCITE-988]
 * FilterToProjectUnifyRule.invert(MutableRel, MutableRel, MutableProject)
 * works incorrectly</a>.
 */
@Test
public void testFilterQueryOnProjectView8() {
    try (TryThreadLocal.Memo ignored = Prepare.THREAD_TRIM.push(true)) {
        MaterializationService.setThreadLocal();
        final String m = "select "salary", "commission",
" + ""deptno", "empid", "name" from "emps"";
        final String v = "select * from "emps" where "name" is null";
        final String q = "select * from V where "commission" is null";
        final JsonBuilder builder = new JsonBuilder();
        final String model = "{
" + "  version: '1.0',
" + "  defaultSchema: 'hr',
" + "  schemas: [
" + "    {
" + "      materializations: [
" + "        {
" + "          table: 'm0',
" + "          view: 'm0v',
" + "          sql: " + builder.toJsonString(m) + "        }
" + "      ],
" + "      tables: [
" + "        {
" + "          name: 'V',
" + "          type: 'view',
" + "          sql: " + builder.toJsonString(v) + "
" + "        }
" + "      ],
" + "      type: 'custom',
" + "      name: 'hr',
" + "      factory: 'org.apache.calcite.adapter.java.ReflectiveSchema$Factory',
" + "      operand: {
" + "        class: 'org.apache.calcite.test.JdbcTest$HrSchema'
" + "      }
" + "    }
" + "  ]
" + "}
";
        CalciteAssert.that().withModel(model).query(q).enableMaterializations(true).explainMatches("", CONTAINS_M0).sameResultWithMaterializationsDisabled();
    }
}

