@Test
public void testTableModify() {
    final String m = "select \"deptno\", \"empid\", \"name\"" + "from \"emps\" where \"deptno\" = 10";
    final String q = "upsert into \"dependents\"" + "select \"empid\" + 1 as x, \"name\"" + "from \"emps\" where \"deptno\" = 10";
    final List<List<List<String>>> substitutedNames = new ArrayList<>();
    try (TryThreadLocal.Memo ignored = Prepare.THREAD_TRIM.push(true)) {
        MaterializationService.setThreadLocal();
        CalciteAssert.that().withMaterializations(HR_FKUK_MODEL, "m0", m).query(q).withHook(Hook.SUB, (Consumer<RelNode>) r -> substitutedNames.add(new TableNameVisitor().run(r))).enableMaterializations(true).explainContains("hr, m0");
    } catch (Exception e) {
        // Table "dependents" not modifiable.
    }
    assertThat(substitutedNames, is(list3(new String[][][] { { { "hr", "m0" } } })));
}

