/**
 * Tests that a projection retains field names after a join.
 */
@Test
public void testProjectJoin() {
    final RelBuilder builder = RelBuilder.create(config().build());
    RelNode root = builder.scan("EMP").as("e").scan("DEPT").join(JoinRelType.INNER).project(builder.field("DEPT", "DEPTNO"), builder.field(0), builder.field("e", "MGR")).// essentially a no-op, was previously throwing exception due to
    // project() using join-renamed fields
    project(builder.field("DEPT", "DEPTNO"), builder.field(1), builder.field("e", "MGR")).build();
    final String expected = "" + "LogicalProject(DEPTNO=[$8], EMPNO=[$0], MGR=[$3])\n" + "  LogicalJoin(condition=[true], joinType=[inner])\n" + "    LogicalTableScan(table=[[scott, EMP]])\n" + "    LogicalTableScan(table=[[scott, DEPT]])\n";
    assertThat(root, hasTree(expected));
}

