@Test
public void testUnionAlias() {
    final RelBuilder builder = RelBuilder.create(config().build());
    RelNode root = builder.scan("EMP").as("e1").project(builder.field("EMPNO"), builder.call(SqlStdOperatorTable.CONCAT, builder.field("ENAME"), builder.literal("-1"))).scan("EMP").as("e2").project(builder.field("EMPNO"), builder.call(SqlStdOperatorTable.CONCAT, builder.field("ENAME"), builder.literal("-2"))).union(// aliases lost here
    false).project(builder.fields(Lists.newArrayList(1, 0))).build();
    final String expected = "" + "LogicalProject($f1=[$1], EMPNO=[$0])\n" + "  LogicalUnion(all=[false])\n" + "    LogicalProject(EMPNO=[$0], $f1=[||($1, '-1')])\n" + "      LogicalTableScan(table=[[scott, EMP]])\n" + "    LogicalProject(EMPNO=[$0], $f1=[||($1, '-2')])\n" + "      LogicalTableScan(table=[[scott, EMP]])\n";
    assertThat(root, hasTree(expected));
}

/**
 * Test case for
 * <a href="https://issues.apache.org/jira/browse/CALCITE-1523">[CALCITE-1523]
 * Add RelBuilder field() method to reference aliased relations not on top of
 * stack</a>, accessing tables aliased that are not accessible in the top
 * RelNode.
 */
@Test
public void testAliasPastTop() {
    // Equivalent SQL:
    //   SELECT *
    //   FROM emp
    //   LEFT JOIN dept ON emp.deptno = dept.deptno
    //     AND emp.empno = 123
    //     AND dept.deptno IS NOT NULL
    final RelBuilder builder = RelBuilder.create(config().build());
    RelNode root = builder.scan("EMP").scan("DEPT").join(JoinRelType.LEFT, builder.call(SqlStdOperatorTable.EQUALS, builder.field(2, "EMP", "DEPTNO"), builder.field(2, "DEPT", "DEPTNO")), builder.call(SqlStdOperatorTable.EQUALS, builder.field(2, "EMP", "EMPNO"), builder.literal(123))).build();
    final String expected = "" + "LogicalJoin(condition=[AND(=($7, $8), =($0, 123))], joinType=[left])\n" + "  LogicalTableScan(table=[[scott, EMP]])\n" + "  LogicalTableScan(table=[[scott, DEPT]])\n";
    assertThat(root, hasTree(expected));
}

/**
 * As {@link #testAliasPastTop()}.
 */
@Test
public void testAliasPastTop2() {
    // Equivalent SQL:
    //   SELECT t1.EMPNO, t2.EMPNO, t3.DEPTNO
    //   FROM emp t1
    //   INNER JOIN emp t2 ON t1.EMPNO = t2.EMPNO
    //   INNER JOIN dept t3 ON t1.DEPTNO = t3.DEPTNO
    //     AND t2.JOB != t3.LOC
    final RelBuilder builder = RelBuilder.create(config().build());
    RelNode root = builder.scan("EMP").as("t1").scan("EMP").as("t2").join(JoinRelType.INNER, builder.equals(builder.field(2, "t1", "EMPNO"), builder.field(2, "t2", "EMPNO"))).scan("DEPT").as("t3").join(JoinRelType.INNER, builder.equals(builder.field(2, "t1", "DEPTNO"), builder.field(2, "t3", "DEPTNO")), builder.not(builder.equals(builder.field(2, "t2", "JOB"), builder.field(2, "t3", "LOC")))).build();
    // Cols:
    // 0-7   EMP as t1
    // 8-15  EMP as t2
    // 16-18 DEPT as t3
    final String expected = "" + "LogicalJoin(condition=[AND(=($7, $16), <>($10, $18))], joinType=[inner])\n" + "  LogicalJoin(condition=[=($0, $8)], joinType=[inner])\n" + "    LogicalTableScan(table=[[scott, EMP]])\n" + "    LogicalTableScan(table=[[scott, EMP]])\n" + "  LogicalTableScan(table=[[scott, DEPT]])\n";
    assertThat(root, hasTree(expected));
}

