    final RelBuilder builder = RelBuilder.create(config().build());
    final RelNode root = builder.scan("EMP").sort(builder.field(2), builder.desc(builder.field(0))).build();
    final String expected = "LogicalSort(sort0=[$2], sort1=[$0], dir0=[ASC], dir1=[DESC])\n" + "  LogicalTableScan(table=[[scott, EMP]])\n";
