/**
 * Test case for
 * <a href="https://issues.apache.org/jira/browse/CALCITE-1610">[CALCITE-1610]
 * RelBuilder sort-combining optimization treats aliases incorrectly</a>.
 */
@Test
public void testSortOverProjectSort() {
    final RelBuilder builder = RelBuilder.create(config().build());
    builder.scan("EMP").sort(0).project(builder.field(1)).// was throwing exception here when attempting to apply to
    // inner sort node
    limit(0, 1).build();
    RelNode root = builder.scan("EMP").sort(0).project(Lists.newArrayList(builder.field(1)), Lists.newArrayList("F1")).limit(0, 1).// make sure we can still access the field by alias
    project(builder.field("F1")).build();
    String expected = "LogicalProject(F1=[$1])\n" + "  LogicalSort(sort0=[$0], dir0=[ASC], fetch=[1])\n" + "    LogicalTableScan(table=[[scott, EMP]])\n";
    assertThat(root, hasTree(expected));
}

/**
 * Tests that a sort on a field followed by a limit gives the same
 * effect as calling sortLimit.
 *
 * <p>In general a relational operator cannot rely on the order of its input,
 * but it is reasonable to merge sort and limit if they were created by
 * consecutive builder operations. And clients such as Piglet rely on it.
 */
@Test
public void testSortThenLimit() {
    final RelBuilder builder = RelBuilder.create(config().build());
    final RelNode root = builder.scan("EMP").sort(builder.desc(builder.field("DEPTNO"))).limit(-1, 10).build();
    final String expected = "" + "LogicalSort(sort0=[$7], dir0=[DESC], fetch=[10])\n" + "  LogicalTableScan(table=[[scott, EMP]])\n";
    assertThat(root, hasTree(expected));
    final RelNode root2 = builder.scan("EMP").sortLimit(-1, 10, builder.desc(builder.field("DEPTNO"))).build();
    assertThat(root2, hasTree(expected));
}

/**
 * Tests that a sort on an expression followed by a limit gives the same
 * effect as calling sortLimit.
 */
@Test
public void testSortExpThenLimit() {
    final RelBuilder builder = RelBuilder.create(config().build());
    final RelNode root = builder.scan("DEPT").sort(builder.desc(builder.call(SqlStdOperatorTable.PLUS, builder.field("DEPTNO"), builder.literal(1)))).limit(3, 10).build();
    final String expected = "" + "LogicalProject(DEPTNO=[$0], DNAME=[$1], LOC=[$2])\n" + "  LogicalSort(sort0=[$3], dir0=[DESC], offset=[3], fetch=[10])\n" + "    LogicalProject(DEPTNO=[$0], DNAME=[$1], LOC=[$2], $f3=[+($0, 1)])\n" + "      LogicalTableScan(table=[[scott, DEPT]])\n";
    assertThat(root, hasTree(expected));
    final RelNode root2 = builder.scan("DEPT").sortLimit(3, 10, builder.desc(builder.call(SqlStdOperatorTable.PLUS, builder.field("DEPTNO"), builder.literal(1)))).build();
    assertThat(root2, hasTree(expected));
}

/**
 * Tests {@link org.apache.calcite.tools.RelRunner} for a VALUES query.
 */
@Test
public void testRunValues() throws Exception {
    // Equivalent SQL:
    //   VALUES (true, 1), (false, -50) AS t(a, b)
    final RelBuilder builder = RelBuilder.create(config().build());
    RelNode root = builder.values(new String[] { "a", "b" }, true, 1, false, -50).build();
    try (PreparedStatement preparedStatement = RelRunners.run(root)) {
        String s = CalciteAssert.toString(preparedStatement.executeQuery());
        final String result = "a=true; b=1\n" + "a=false; b=-50\n";
        assertThat(s, is(result));
    }
}

/**
 * Tests {@link org.apache.calcite.tools.RelRunner} for a table scan + filter
 * query.
 */
@Test
public void testRun() throws Exception {
    // Equivalent SQL:
    //   SELECT * FROM EMP WHERE DEPTNO = 20
    final RelBuilder builder = RelBuilder.create(config().build());
    RelNode root = builder.scan("EMP").filter(builder.equals(builder.field("DEPTNO"), builder.literal(20))).build();
    // Note that because the table has been resolved in the RelNode tree
    // we do not need to supply a "schema" as context to the runner.
    try (PreparedStatement preparedStatement = RelRunners.run(root)) {
        String s = CalciteAssert.toString(preparedStatement.executeQuery());
        final String result = "" + "EMPNO=7369; ENAME=SMITH; JOB=CLERK; MGR=7902; HIREDATE=1980-12-17; SAL=800.00; COMM=null; DEPTNO=20\n" + "EMPNO=7566; ENAME=JONES; JOB=MANAGER; MGR=7839; HIREDATE=1981-02-04; SAL=2975.00; COMM=null; DEPTNO=20\n" + "EMPNO=7788; ENAME=SCOTT; JOB=ANALYST; MGR=7566; HIREDATE=1987-04-19; SAL=3000.00; COMM=null; DEPTNO=20\n" + "EMPNO=7876; ENAME=ADAMS; JOB=CLERK; MGR=7788; HIREDATE=1987-05-23; SAL=1100.00; COMM=null; DEPTNO=20\n" + "EMPNO=7902; ENAME=FORD; JOB=ANALYST; MGR=7566; HIREDATE=1981-12-03; SAL=3000.00; COMM=null; DEPTNO=20\n";
        assertThat(s, is(result));
    }
}

/**
 * Test case for
 * <a href="https://issues.apache.org/jira/browse/CALCITE-1595">[CALCITE-1595]
 * RelBuilder.call throws NullPointerException if argument types are
 * invalid</a>.
 */
@Test
public void testTypeInferenceValidation() {
    final RelBuilder builder = RelBuilder.create(config().build());
    // test for a) call(operator, Iterable<RexNode>)
    final RexNode arg0 = builder.literal(0);
    final RexNode arg1 = builder.literal("xyz");
    try {
        builder.call(SqlStdOperatorTable.PLUS, Lists.newArrayList(arg0, arg1));
        fail("Invalid combination of parameter types");
    } catch (IllegalArgumentException e) {
        assertThat(e.getMessage(), containsString("Cannot infer return type"));
    }
    // test for b) call(operator, RexNode...)
    try {
        builder.call(SqlStdOperatorTable.PLUS, arg0, arg1);
        fail("Invalid combination of parameter types");
    } catch (IllegalArgumentException e) {
        assertThat(e.getMessage(), containsString("Cannot infer return type"));
    }
}

@Test
public void testMatchRecognize() {
    // Equivalent SQL:
    //   SELECT *
    //   FROM emp
    //   MATCH_RECOGNIZE (
    //     PARTITION BY deptno
    //     ORDER BY empno asc
    //     MEASURES
    //       STRT.mgr as start_nw,
    //       LAST(DOWN.mgr) as bottom_nw,
    //     PATTERN (STRT DOWN+ UP+) WITHIN INTERVAL '5' SECOND
    //     DEFINE
    //       DOWN as DOWN.mgr < PREV(DOWN.mgr),
    //       UP as UP.mgr > PREV(UP.mgr)
    //   )
    final RelBuilder builder = RelBuilder.create(config().build()).scan("EMP");
    final RelDataTypeFactory typeFactory = builder.getTypeFactory();
    final RelDataType intType = typeFactory.createSqlType(SqlTypeName.INTEGER);
    RexNode pattern = builder.patternConcat(builder.literal("STRT"), builder.patternQuantify(builder.literal("DOWN"), builder.literal(1), builder.literal(-1), builder.literal(false)), builder.patternQuantify(builder.literal("UP"), builder.literal(1), builder.literal(-1), builder.literal(false)));
    ImmutableMap.Builder<String, RexNode> pdBuilder = new ImmutableMap.Builder<>();
    RexNode downDefinition = builder.call(SqlStdOperatorTable.LESS_THAN, builder.call(SqlStdOperatorTable.PREV, builder.patternField("DOWN", intType, 3), builder.literal(0)), builder.call(SqlStdOperatorTable.PREV, builder.patternField("DOWN", intType, 3), builder.literal(1)));
    pdBuilder.put("DOWN", downDefinition);
    RexNode upDefinition = builder.call(SqlStdOperatorTable.GREATER_THAN, builder.call(SqlStdOperatorTable.PREV, builder.patternField("UP", intType, 3), builder.literal(0)), builder.call(SqlStdOperatorTable.PREV, builder.patternField("UP", intType, 3), builder.literal(1)));
    pdBuilder.put("UP", upDefinition);
    ImmutableList.Builder<RexNode> measuresBuilder = new ImmutableList.Builder<>();
    measuresBuilder.add(builder.alias(builder.patternField("STRT", intType, 3), "start_nw"));
    measuresBuilder.add(builder.alias(builder.call(SqlStdOperatorTable.LAST, builder.patternField("DOWN", intType, 3), builder.literal(0)), "bottom_nw"));
    RexNode after = builder.getRexBuilder().makeFlag(SqlMatchRecognize.AfterOption.SKIP_TO_NEXT_ROW);
    ImmutableList.Builder<RexNode> partitionKeysBuilder = new ImmutableList.Builder<>();
    partitionKeysBuilder.add(builder.field("DEPTNO"));
    ImmutableList.Builder<RexNode> orderKeysBuilder = new ImmutableList.Builder<>();
    orderKeysBuilder.add(builder.field("EMPNO"));
    RexNode interval = builder.literal("INTERVAL '5' SECOND");
    final ImmutableMap<String, TreeSet<String>> subsets = ImmutableMap.of();
    final RelNode root = builder.match(pattern, false, false, pdBuilder.build(), measuresBuilder.build(), after, subsets, false, partitionKeysBuilder.build(), orderKeysBuilder.build(), interval).build();
    final String expected = "LogicalMatch(partition=[[$7]], order=[[0]], " + "outputFields=[[$7, 'start_nw', 'bottom_nw']], allRows=[false], " + "after=[FLAG(SKIP TO NEXT ROW)], pattern=[(('STRT', " + "PATTERN_QUANTIFIER('DOWN', 1, -1, false)), " + "PATTERN_QUANTIFIER('UP', 1, -1, false))], " + "isStrictStarts=[false], isStrictEnds=[false], " + "interval=['INTERVAL ''5'' SECOND'], subsets=[[]], " + "patternDefinitions=[[<(PREV(DOWN.$3, 0), PREV(DOWN.$3, 1)), " + ">(PREV(UP.$3, 0), PREV(UP.$3, 1))]], " + "inputFields=[[EMPNO, ENAME, JOB, MGR, HIREDATE, SAL, COMM, DEPTNO]])\n" + "  LogicalTableScan(table=[[scott, EMP]])\n";
    assertThat(root, hasTree(expected));
}

