@Test
public void testExpandTable() throws SQLException {
    final RelOptTable.ViewExpander viewExpander = (rowType, queryString, schemaPath, viewPath) -> null;
    final RelFactories.TableScanFactory tableScanFactory = RelFactories.expandingScanFactory(viewExpander, RelFactories.DEFAULT_TABLE_SCAN_FACTORY);
    try (Connection connection = DriverManager.getConnection("jdbc:calcite:")) {
        // First, use a non-expanding RelBuilder. Plan contains LogicalTableScan.
        final Frameworks.ConfigBuilder configBuilder = expandingConfig(connection);
        final RelBuilder builder = RelBuilder.create(configBuilder.build());
        final String expected = "LogicalFilter(condition=[>($2, 10)])\n" + "  LogicalTableScan(table=[[JDBC_SCOTT, EMP]])\n";
        checkExpandTable(builder, hasTree(expected));
        // Next, use an expanding RelBuilder. Plan contains JdbcTableScan,
        // because RelBuilder.scan has called RelOptTable.toRel.
        final FrameworkConfig config = configBuilder.context(Contexts.of(tableScanFactory)).build();
        final RelBuilder builder2 = RelBuilder.create(config);
        final String expected2 = "LogicalFilter(condition=[>($2, 10)])\n" + "  JdbcTableScan(table=[[JDBC_SCOTT, EMP]])\n";
        checkExpandTable(builder2, hasTree(expected2));
    }
}

