@Test
public void testProjectCorrelateTransposeRuleSemiCorrelate() {
    RelBuilder relBuilder = RelBuilder.create(RelBuilderTest.config().build());
    RelNode left = relBuilder.values(new String[] { "f", "f2" }, "1", "2").build();
    CorrelationId correlationId = new CorrelationId(0);
    RexNode rexCorrel = relBuilder.getRexBuilder().makeCorrel(left.getRowType(), correlationId);
    RelNode right = relBuilder.values(new String[] { "f3", "f4" }, "1", "2").project(relBuilder.field(0), relBuilder.getRexBuilder().makeFieldAccess(rexCorrel, 0)).build();
    LogicalCorrelate correlate = new LogicalCorrelate(left.getCluster(), left.getTraitSet(), left, right, correlationId, ImmutableBitSet.of(0), SemiJoinType.SEMI);
    relBuilder.push(correlate);
    RelNode relNode = relBuilder.project(relBuilder.field(0)).build();
    HepProgram program = new HepProgramBuilder().addRuleInstance(ProjectCorrelateTransposeRule.INSTANCE).build();
    HepPlanner hepPlanner = new HepPlanner(program);
    hepPlanner.setRoot(relNode);
    RelNode output = hepPlanner.findBestExp();
    final String planAfter = NL + RelOptUtil.toString(output);
    final DiffRepository diffRepos = getDiffRepos();
    diffRepos.assertEquals("planAfter", "${planAfter}", planAfter);
    SqlToRelTestBase.assertValid(output);
}

