/**
 * Test case for
 * <a href="https://issues.apache.org/jira/browse/CALCITE-2638">[CALCITE-2638]
 * Constant reducer must not duplicate calls to non-deterministic
 * functions</a>.
 */
@Test
public void testReduceConstantsNonDeterministicFunction() {
    final DiffRepository diffRepos = getDiffRepos();
    final SqlOperator nonDeterministicOp = new SqlSpecialOperator("NDC", SqlKind.OTHER_FUNCTION, 0, false, ReturnTypes.INTEGER, null, null) {

        @Override
        public boolean isDeterministic() {
            return false;
        }
    };
    // Build a tree equivalent to the SQL
    //  SELECT sal, n
    //  FROM (SELECT sal, NDC() AS n FROM emp)
    //  WHERE n > 10
    final RelBuilder builder = RelBuilder.create(RelBuilderTest.config().build());
    final RelNode root = builder.scan("EMP").project(builder.field("SAL"), builder.alias(builder.call(nonDeterministicOp), "N")).filter(builder.call(SqlStdOperatorTable.GREATER_THAN, builder.field("N"), builder.literal(10))).build();
    HepProgram preProgram = new HepProgramBuilder().build();
    HepPlanner prePlanner = new HepPlanner(preProgram);
    prePlanner.setRoot(root);
    final RelNode relBefore = prePlanner.findBestExp();
    final String planBefore = NL + RelOptUtil.toString(relBefore);
    diffRepos.assertEquals("planBefore", "${planBefore}", planBefore);
    final HepProgram program = new HepProgramBuilder().addRuleInstance(ReduceExpressionsRule.FILTER_INSTANCE).addRuleInstance(ReduceExpressionsRule.PROJECT_INSTANCE).build();
    HepPlanner hepPlanner = new HepPlanner(program);
    hepPlanner.setRoot(root);
    final RelNode relAfter = hepPlanner.findBestExp();
    final String planAfter = NL + RelOptUtil.toString(relAfter);
    diffRepos.assertEquals("planAfter", "${planAfter}", planAfter);
}

