    final AggregateExtractProjectRule rule = new AggregateExtractProjectRule(operand(Aggregate.class, operandJ(Project.class, null, new Predicate<Project>() {

        int matchCount = 0;

        public boolean test(Project project) {
            return matchCount++ == 0;
        }
    }, none())), RelFactories.LOGICAL_BUILDER);
    sql(sql).withPre(pre).withRule(rule).checkUnchanged();
}

