    assertJsonQuery(SqlFunctions.PathContext.withReturned(SqlFunctions.PathMode.LAX, "bar"), SqlJsonQueryWrapperBehavior.WITHOUT_ARRAY, SqlJsonQueryEmptyOrErrorBehavior.EMPTY_OBJECT, SqlJsonQueryEmptyOrErrorBehavior.NULL, is("{}"));
    assertJsonQueryFailed(SqlFunctions.PathContext.withReturned(SqlFunctions.PathMode.LAX, "bar"), SqlJsonQueryWrapperBehavior.WITHOUT_ARRAY, SqlJsonQueryEmptyOrErrorBehavior.ERROR, SqlJsonQueryEmptyOrErrorBehavior.NULL, errorMatches(new CalciteException("Empty result of JSON_QUERY function is not " + "allowed", null)));
    assertJsonQuery(SqlFunctions.PathContext.withStrictException(new Exception("test message")), SqlJsonQueryWrapperBehavior.WITHOUT_ARRAY, SqlJsonQueryEmptyOrErrorBehavior.NULL, SqlJsonQueryEmptyOrErrorBehavior.EMPTY_ARRAY, is("[]"));
    assertJsonQuery(SqlFunctions.PathContext.withStrictException(new Exception("test message")), SqlJsonQueryWrapperBehavior.WITHOUT_ARRAY, SqlJsonQueryEmptyOrErrorBehavior.NULL, SqlJsonQueryEmptyOrErrorBehavior.EMPTY_OBJECT, is("{}"));
    assertJsonQueryFailed(SqlFunctions.PathContext.withStrictException(new Exception("test message")), SqlJsonQueryWrapperBehavior.WITHOUT_ARRAY, SqlJsonQueryEmptyOrErrorBehavior.NULL, SqlJsonQueryEmptyOrErrorBehavior.ERROR, errorMatches(new RuntimeException("java.lang.Exception: test message")));
    assertJsonQuery(SqlFunctions.PathContext.withReturned(SqlFunctions.PathMode.STRICT, "bar"), SqlJsonQueryWrapperBehavior.WITHOUT_ARRAY, SqlJsonQueryEmptyOrErrorBehavior.NULL, SqlJsonQueryEmptyOrErrorBehavior.NULL, nullValue());
    assertJsonQuery(SqlFunctions.PathContext.withReturned(SqlFunctions.PathMode.STRICT, "bar"), SqlJsonQueryWrapperBehavior.WITHOUT_ARRAY, SqlJsonQueryEmptyOrErrorBehavior.NULL, SqlJsonQueryEmptyOrErrorBehavior.EMPTY_ARRAY, is("[]"));
    assertJsonQueryFailed(SqlFunctions.PathContext.withReturned(SqlFunctions.PathMode.STRICT, "bar"), SqlJsonQueryWrapperBehavior.WITHOUT_ARRAY, SqlJsonQueryEmptyOrErrorBehavior.NULL, SqlJsonQueryEmptyOrErrorBehavior.ERROR, errorMatches(new CalciteException("Strict jsonpath mode requires array or " + "object value, and the actual value is: 'bar'", null)));
    // wrapper behavior test
    assertJsonQuery(SqlFunctions.PathContext.withReturned(SqlFunctions.PathMode.STRICT, "bar"), SqlJsonQueryWrapperBehavior.WITH_UNCONDITIONAL_ARRAY, SqlJsonQueryEmptyOrErrorBehavior.NULL, SqlJsonQueryEmptyOrErrorBehavior.NULL, is("[\"bar\"]"));
    assertJsonQuery(SqlFunctions.PathContext.withReturned(SqlFunctions.PathMode.STRICT, "bar"), SqlJsonQueryWrapperBehavior.WITH_CONDITIONAL_ARRAY, SqlJsonQueryEmptyOrErrorBehavior.NULL, SqlJsonQueryEmptyOrErrorBehavior.NULL, is("[\"bar\"]"));
    assertJsonQuery(SqlFunctions.PathContext.withReturned(SqlFunctions.PathMode.STRICT, Collections.singletonList("bar")), SqlJsonQueryWrapperBehavior.WITH_UNCONDITIONAL_ARRAY, SqlJsonQueryEmptyOrErrorBehavior.NULL, SqlJsonQueryEmptyOrErrorBehavior.NULL, is("[[\"bar\"]]"));
    assertJsonQuery(SqlFunctions.PathContext.withReturned(SqlFunctions.PathMode.STRICT, Collections.singletonList("bar")), SqlJsonQueryWrapperBehavior.WITH_CONDITIONAL_ARRAY, SqlJsonQueryEmptyOrErrorBehavior.NULL, SqlJsonQueryEmptyOrErrorBehavior.NULL, is("[\"bar\"]"));
}

