    // the return type there usually needs to be a final CAST to get the
    // result back to match the type of x.
    final String sql = "select sum(sal) over w1,\n" + "  avg(sal) over w1\n" + "from emp\n" + "window w1 as (partition by job order by hiredate rows 2 preceding)";
    sql(sql).ok();
}

