/**
 * Tests that a window containing only ORDER BY is implicitly CURRENT ROW.
 */
@Test
public void testOverOrderWindow() {
    final String sql = "select last_value(deptno) over w\n" + "from emp\n" + "window w as (order by empno)";
    sql(sql).ok();
    // Same query using inline window
    final String sql2 = "select last_value(deptno) over (order by empno)\n" + "from emp\n";
    sql(sql2).ok();
}

/**
 * Tests that a window with a FOLLOWING bound becomes BETWEEN CURRENT ROW
 * AND FOLLOWING.
 */
@Test
public void testOverOrderFollowingWindow() {
    // Window contains only ORDER BY (implicitly CURRENT ROW).
    final String sql = "select last_value(deptno) over w\n" + "from emp\n" + "window w as (order by empno rows 2 following)";
    sql(sql).ok();
    // Same query using inline window
    final String sql2 = "select\n" + "  last_value(deptno) over (order by empno rows 2 following)\n" + "from emp\n";
    sql(sql2).ok();
}

