    checkWholeExpFails("LOCALTIMESTAMP(1+2)", "Argument to function 'LOCALTIMESTAMP' must be a literal");
    checkWholeExpFails("LOCALTIMESTAMP()", "No match found for function signature LOCALTIMESTAMP..");
    // with TZ?
