    checkWholeExpFails("LOCALTIMESTAMP(-1)", "Argument to function 'LOCALTIMESTAMP' must be a positive integer literal");
    checkExpFails("^LOCALTIMESTAMP(100000000000000)^", "(?s).*Numeric literal '100000000000000' out of range.*");
    checkWholeExpFails("LOCALTIMESTAMP(4)", "Argument to function 'LOCALTIMESTAMP' must be a valid precision between '0' and '3'");
    checkWholeExpFails("LOCALTIMESTAMP('foo')", "(?s).*Cannot apply.*");
    // CURRENT_DATE
    checkWholeExpFails("CURRENT_DATE(3)", "No match found for function signature CURRENT_DATE..NUMERIC..");
    //    fix sqlcontext later.
    checkExp("CURRENT_DATE");
    checkWholeExpFails("CURRENT_DATE(1+2)", "No match found for function signature CURRENT_DATE..NUMERIC..");
    checkWholeExpFails("CURRENT_DATE()", "No match found for function signature CURRENT_DATE..");
    //  with TZ?
    checkExpType("CURRENT_DATE", "DATE NOT NULL");
