@Test
public void testJdbcFunctionCall() {
    checkExp("{fn log10(1)}");
    checkExp("{fn locate('','')}");
    checkExp("{fn insert('',1,2,'')}");
    // 'lower' is a valid SQL function but not valid JDBC fn; the JDBC
    // equivalent is 'lcase'
    checkWholeExpFails("{fn lower('Foo' || 'Bar')}", "Function '\\{fn LOWER\\}' is not defined");
    checkExp("{fn lcase('Foo' || 'Bar')}");
    checkExp("{fn power(2, 3)}");
    checkWholeExpFails("{fn insert('','',1,2)}", "(?s).*.*");
    checkWholeExpFails("{fn insert('','',1)}", "(?s).*4.*");
    checkExp("{fn locate('','',1)}");
    checkWholeExpFails("{fn log10('1')}", "(?s).*Cannot apply.*fn LOG10..<CHAR.1.>.*");
    final String expected = "Cannot apply '\\{fn LOG10\\}' to arguments of" + " type '\\{fn LOG10\\}\\(<INTEGER>, <INTEGER>\\)'\\. " + "Supported form\\(s\\): '\\{fn LOG10\\}\\(<NUMERIC>\\)'";
    checkWholeExpFails("{fn log10(1,1)}", expected);
    checkWholeExpFails("{fn fn(1)}", "(?s).*Function '.fn FN.' is not defined.*");
    checkWholeExpFails("{fn hahaha(1)}", "(?s).*Function '.fn HAHAHA.' is not defined.*");
}

