@Test
public void testNameResolutionInValuesClause() {
    final String emps = "(select 1 as empno, 'x' as name, 10 as deptno, 'M' as gender, 'San Francisco' as city, 30 as empid, 25 as age from (values (1)))";
    final String depts = "(select 10 as deptno, 'Sales' as name from (values (1)))";
    checkFails("select * from " + emps + " join " + depts + "\n" + " on ^emps^.deptno = deptno", "Table 'EMPS' not found");
    // this is ok
    check("select * from " + emps + " as e\n" + " join " + depts + " as d\n" + " on e.deptno = d.deptno");
    // fail: ambiguous column in WHERE
    checkFails("select * from " + emps + " as emps,\n" + " " + depts + "\n" + "where ^deptno^ > 5", "Column 'DEPTNO' is ambiguous");
    // fail: ambiguous column reference in ON clause
    checkFails("select * from " + emps + " as e\n" + " join " + depts + " as d\n" + " on e.deptno = ^deptno^", "Column 'DEPTNO' is ambiguous");
    // ok: column 'age' is unambiguous
    check("select * from " + emps + " as e\n" + " join " + depts + " as d\n" + " on e.deptno = age");
    // ok: reference to derived column
    check("select * from " + depts + "\n" + " join (select mod(age, 30) as agemod from " + emps + ")\n" + "on deptno = agemod");
    // fail: deptno is ambiguous
    checkFails("select name from " + depts + "\n" + "join (select mod(age, 30) as agemod, deptno from " + emps + ")\n" + "on ^deptno^ = agemod", "Column 'DEPTNO' is ambiguous");
    // fail: lateral reference
    checkFails("select * from " + emps + " as e,\n" + " (select 1, ^e^.deptno from (values(true))) as d", "Table 'E' not found");
}

