    // non-disjoint bit sets
    assertThat(cube(ImmutableBitSet.of(1, 4), ImmutableBitSet.of(3, 4)).toString(), equalTo("[{1, 3, 4}, {1, 4}, {3, 4}, {}]"));
    // some bit sets are empty, and there are duplicates
    assertThat(cube(ImmutableBitSet.of(1, 4), ImmutableBitSet.of(), ImmutableBitSet.of(1, 4), ImmutableBitSet.of(3, 4), ImmutableBitSet.of()).toString(), equalTo("[{1, 3, 4}, {1, 4}, {3, 4}, {}]"));
    assertThat(cube(ImmutableBitSet.of(1)).toString(), equalTo("[{1}, {}]"));
    assertThat(cube(ImmutableBitSet.of()).toString(), equalTo("[{}]"));
    assertThat(cube().toString(), equalTo("[{}]"));
}

@Test
public void testGrouping() {
