@Test
public void testJoinUsing() {
    final String empDeptType = "RecordType(INTEGER NOT NULL DEPTNO," + " INTEGER NOT NULL EMPNO," + " VARCHAR(20) NOT NULL ENAME," + " VARCHAR(10) NOT NULL JOB," + " INTEGER MGR," + " TIMESTAMP(0) NOT NULL HIREDATE," + " INTEGER NOT NULL SAL," + " INTEGER NOT NULL COMM," + " BOOLEAN NOT NULL SLACKER," + " VARCHAR(10) NOT NULL NAME) NOT NULL";
    sql("select * from emp join dept using (deptno)").ok().type(empDeptType);
    // NATURAL has same effect as USING
    sql("select * from emp natural join dept").ok().type(empDeptType);
    // fail: comm exists on one side not the other
    // todo: The error message could be improved.
    checkFails("select * from emp join dept using (deptno, ^comm^)", "Column 'COMM' not found in any table");
    checkFails("select * from emp join dept using (^empno^)", "Column 'EMPNO' not found in any table");
    checkFails("select * from dept join emp using (^empno^)", "Column 'EMPNO' not found in any table");
    // not on either side
    checkFails("select * from dept join emp using (^abc^)", "Column 'ABC' not found in any table");
    // column exists, but wrong case
    checkFails("select * from dept join emp using (^\"deptno\"^)", "Column 'deptno' not found in any table");
    // ok to repeat (ok in Oracle10g too)
    final String sql = "select * from emp join dept using (deptno, deptno)";
    sql(sql).ok().type(empDeptType);
    // inherited column, not found in either side of the join, in the
    // USING clause
    checkFails("select * from dept where exists (\n" + "select 1 from emp join bonus using (^dname^))", "Column 'DNAME' not found in any table");
    // inherited column, found in only one side of the join, in the
    // USING clause
    checkFails("select * from dept where exists (\n" + "select 1 from emp join bonus using (^deptno^))", "Column 'DEPTNO' not found in any table");
}

