@Test
public void testOrderUnion() {
    check("select empno, sal from emp " + "union all " + "select deptno, deptno from dept " + "order by empno");
    checkFails("select empno, sal from emp " + "union all " + "select deptno, deptno from dept " + "order by ^asc^", "Column 'ASC' not found in any table");
