    check("select empno, sal from emp " + "union all " + "select deptno, deptno from dept " + "order by 2");
    // ordinal out of range -- if 'order by <ordinal>' means something in
    // this dialect
    if (tester.getConformance().isSortByOrdinal()) {
        checkFails("select empno, sal from emp " + "union all " + "select deptno, deptno from dept " + "order by ^3^", "Ordinal out of range");
    }
    // Expressions made up of aliases are OK.
    // (This is illegal in Oracle 10G.)
    check("select empno, sal from emp " + "union all " + "select deptno, deptno from dept " + "order by empno * sal + 2");
