/**
 * Tests validation of the ORDER BY clause when GROUP BY is present.
 */
@Test
public void testOrderGroup() {
    // Group by
    checkFails("select 1 from emp group by deptno order by ^empno^", "Expression 'EMPNO' is not being grouped");
    // order by can contain aggregate expressions
    check("select empno from emp " + "group by empno, deptno " + "order by deptno * sum(sal + 2)");
    // Having
    checkFails("select sum(sal) from emp having count(*) > 3 order by ^empno^", "Expression 'EMPNO' is not being grouped");
    check("select sum(sal) from emp having count(*) > 3 order by sum(deptno)");
    // Select distinct
    checkFails("select distinct deptno from emp group by deptno order by ^empno^", "Expression 'EMPNO' is not in the select clause");
    checkFails("select distinct deptno from emp group by deptno order by deptno, ^empno^", "Expression 'EMPNO' is not in the select clause");
    check("select distinct deptno from emp group by deptno order by deptno");
    // UNION of SELECT DISTINCT and GROUP BY behaves just like a UNION.
    check("select distinct deptno from dept " + "union all " + "select empno from emp group by deptno, empno " + "order by deptno");
    // order by can contain a mixture of aliases and aggregate expressions
    check("select empno as x " + "from emp " + "group by empno, deptno " + "order by x * sum(sal + 2)");
    sql("select empno as x " + "from emp " + "group by empno, deptno " + "order by empno * sum(sal + 2)").failsIf(tester.getConformance().isSortByAliasObscures(), "xxxx");
}

/**
 * Tests validation of the aliases in GROUP BY.
 *
 * <p>Test case for
 * <a href="https://issues.apache.org/jira/browse/CALCITE-1306">[CALCITE-1306]
 * Allow GROUP BY and HAVING to reference SELECT expressions by ordinal and
 * alias</a>.
 *
 * @see SqlConformance#isGroupByAlias()
 */
@Test
public void testAliasInGroupBy() {
    final SqlTester lenient = tester.withConformance(SqlConformanceEnum.LENIENT);
    final SqlTester strict = tester.withConformance(SqlConformanceEnum.STRICT_2003);
    // Group by
    sql("select empno as e from emp group by ^e^").tester(strict).fails("Column 'E' not found in any table").tester(lenient).sansCarets().ok();
    sql("select empno as e from emp group by ^e^").tester(strict).fails("Column 'E' not found in any table").tester(lenient).sansCarets().ok();
    sql("select emp.empno as e from emp group by ^e^").tester(strict).fails("Column 'E' not found in any table").tester(lenient).sansCarets().ok();
    sql("select e.empno from emp as e group by e.empno").tester(strict).ok().tester(lenient).ok();
    sql("select e.empno as eno from emp as e group by ^eno^").tester(strict).fails("Column 'ENO' not found in any table").tester(lenient).sansCarets().ok();
    sql("select deptno as dno from emp group by cube(^dno^)").tester(strict).fails("Column 'DNO' not found in any table").tester(lenient).sansCarets().ok();
    sql("select deptno as dno, ename name, sum(sal) from emp\n" + "group by grouping sets ((^dno^), (name, deptno))").tester(strict).fails("Column 'DNO' not found in any table").tester(lenient).sansCarets().ok();
    sql("select ename as deptno from emp as e join dept as d on " + "e.deptno = d.deptno group by ^deptno^").tester(lenient).sansCarets().ok();
    sql("select t.e, count(*) from (select empno as e from emp) t group by e").tester(strict).ok().tester(lenient).ok();
    // The following 2 tests have the same SQL but fail for different reasons.
    sql("select t.e, count(*) as c from " + " (select empno as e from emp) t group by e,^c^").tester(strict).fails("Column 'C' not found in any table");
    sql("select t.e, ^count(*)^ as c from " + " (select empno as e from emp) t group by e,c").tester(lenient).fails(ERR_AGG_IN_GROUP_BY);
    sql("select t.e, e + ^count(*)^ as c from " + " (select empno as e from emp) t group by e,c").tester(lenient).fails(ERR_AGG_IN_GROUP_BY);
    sql("select t.e, e + ^count(*)^ as c from " + " (select empno as e from emp) t group by e,2").tester(lenient).fails(ERR_AGG_IN_GROUP_BY).tester(strict).sansCarets().ok();
    sql("select deptno,(select empno + 1 from emp) eno\n" + "from dept group by deptno,^eno^").tester(strict).fails("Column 'ENO' not found in any table").tester(lenient).sansCarets().ok();
    sql("select empno as e, deptno as e\n" + "from emp group by ^e^").tester(lenient).fails("Column 'E' is ambiguous");
    sql("select empno, ^count(*)^ c from emp group by empno, c").tester(lenient).fails(ERR_AGG_IN_GROUP_BY);
    sql("select deptno + empno as d, deptno + empno + mgr from emp" + " group by d,mgr").tester(lenient).sansCarets().ok();
    // When alias is equal to one or more columns in the query then giving
    // priority to alias. But Postgres may throw ambiguous column error or give
    // priority to column name.
    sql("select count(*) from (\n" + "  select ename AS deptno FROM emp GROUP BY deptno) t").tester(lenient).sansCarets().ok();
    sql("select count(*) from " + "(select ename AS deptno FROM emp, dept GROUP BY deptno) t").tester(lenient).sansCarets().ok();
    sql("select empno + deptno AS \"z\" FROM emp GROUP BY \"Z\"").tester(lenient.withCaseSensitive(false)).sansCarets().ok();
    sql("select empno + deptno as c, ^c^ + mgr as d from emp group by c, d").tester(lenient).fails("Column 'C' not found in any table");
    // Group by alias with strict conformance should fail.
    sql("select empno as e from emp group by ^e^").tester(strict).fails("Column 'E' not found in any table");
}

/**
 * Tests validation of ordinals in GROUP BY.
 *
 * @see SqlConformance#isGroupByOrdinal()
 */
@Test
public void testOrdinalInGroupBy() {
    final SqlTester lenient = tester.withConformance(SqlConformanceEnum.LENIENT);
    final SqlTester strict = tester.withConformance(SqlConformanceEnum.STRICT_2003);
    sql("select ^empno^,deptno from emp group by 1, deptno").tester(strict).fails("Expression 'EMPNO' is not being grouped").tester(lenient).sansCarets().ok();
    sql("select ^emp.empno^ as e from emp group by 1").tester(strict).fails("Expression 'EMP.EMPNO' is not being grouped").tester(lenient).sansCarets().ok();
    sql("select 2 + ^emp.empno^ + 3 as e from emp group by 1").tester(strict).fails("Expression 'EMP.EMPNO' is not being grouped").tester(lenient).sansCarets().ok();
    sql("select ^e.empno^ from emp as e group by 1").tester(strict).fails("Expression 'E.EMPNO' is not being grouped").tester(lenient).sansCarets().ok();
    sql("select e.empno from emp as e group by 1, empno").tester(strict).ok().tester(lenient).sansCarets().ok();
    sql("select ^e.empno^ as eno from emp as e group by 1").tester(strict).fails("Expression 'E.EMPNO' is not being grouped").tester(lenient).sansCarets().ok();
    sql("select ^deptno^ as dno from emp group by cube(1)").tester(strict).fails("Expression 'DEPTNO' is not being grouped").tester(lenient).sansCarets().ok();
    sql("select 1 as dno from emp group by cube(1)").tester(strict).ok().tester(lenient).sansCarets().ok();
    sql("select deptno as dno, ename name, sum(sal) from emp\n" + "group by grouping sets ((1), (^name^, deptno))").tester(strict).fails("Column 'NAME' not found in any table").tester(lenient).sansCarets().ok();
    sql("select ^e.deptno^ from emp as e\n" + "join dept as d on e.deptno = d.deptno group by 1").tester(strict).fails("Expression 'E.DEPTNO' is not being grouped").tester(lenient).sansCarets().ok();
    sql("select ^deptno^,(select empno from emp) eno from dept" + " group by 1,2").tester(strict).fails("Expression 'DEPTNO' is not being grouped").tester(lenient).sansCarets().ok();
    sql("select ^empno^, count(*) from emp group by 1 order by 1").tester(strict).fails("Expression 'EMPNO' is not being grouped").tester(lenient).sansCarets().ok();
    sql("select ^empno^ eno, count(*) from emp group by 1 order by 1").tester(strict).fails("Expression 'EMPNO' is not being grouped").tester(lenient).sansCarets().ok();
    sql("select count(*) from (select 1 from emp" + " group by substring(ename from 2 for 3))").tester(strict).ok().tester(lenient).sansCarets().ok();
    sql("select deptno from emp group by deptno, ^100^").tester(lenient).fails("Ordinal out of range").tester(strict).sansCarets().ok();
    // Calcite considers integers in GROUP BY to be constants, so test passes.
    // Postgres considers them ordinals and throws out of range position error.
    sql("select deptno from emp group by ^100^, deptno").tester(lenient).fails("Ordinal out of range").tester(strict).sansCarets().ok();
}

/**
 * Tests validation of the aliases in HAVING.
 *
 * @see SqlConformance#isHavingAlias()
 */
@Test
public void testAliasInHaving() {
    final SqlTester lenient = tester.withConformance(SqlConformanceEnum.LENIENT);
    final SqlTester strict = tester.withConformance(SqlConformanceEnum.STRICT_2003);
    sql("select count(empno) as e from emp having ^e^ > 10").tester(strict).fails("Column 'E' not found in any table").tester(lenient).sansCarets().ok();
    sql("select emp.empno as e from emp group by ^e^ having e > 10").tester(strict).fails("Column 'E' not found in any table").tester(lenient).sansCarets().ok();
    sql("select emp.empno as e from emp group by empno having ^e^ > 10").tester(strict).fails("Column 'E' not found in any table").tester(lenient).sansCarets().ok();
    sql("select e.empno from emp as e group by 1 having ^e.empno^ > 10").tester(strict).fails("Expression 'E.EMPNO' is not being grouped").tester(lenient).sansCarets().ok();
    // When alias is equal to one or more columns in the query then giving
    // priority to alias, but PostgreSQL throws ambiguous column error or gives
    // priority to column name.
    sql("select count(empno) as deptno from emp having ^deptno^ > 10").tester(strict).fails("Expression 'DEPTNO' is not being grouped").tester(lenient).sansCarets().ok();
    // Alias in aggregate is not allowed.
    sql("select empno as e from emp having max(^e^) > 10").tester(strict).fails("Column 'E' not found in any table").tester(lenient).fails("Column 'E' not found in any table");
    sql("select count(empno) as e from emp having ^e^ > 10").tester(strict).fails("Column 'E' not found in any table").tester(lenient).sansCarets().ok();
}

/**
 * Tests validation of the ORDER BY clause when DISTINCT is present.
 */
@Test
public void testOrderDistinct() {
    // Distinct on expressions with attempts to order on a column in
    // the underlying table
    checkFails("select distinct cast(empno as bigint) " + "from emp order by ^empno^", "Expression 'EMPNO' is not in the select clause");
    checkFails("select distinct cast(empno as bigint) " + "from emp order by ^emp.empno^", "Expression 'EMP\\.EMPNO' is not in the select clause");
    checkFails("select distinct cast(empno as bigint) as empno " + "from emp order by ^emp.empno^", "Expression 'EMP\\.EMPNO' is not in the select clause");
    checkFails("select distinct cast(empno as bigint) as empno " + "from emp as e order by ^e.empno^", "Expression 'E\\.EMPNO' is not in the select clause");
    // These tests are primarily intended to test cases where sorting by
    // an alias is allowed.  But for instances that don't support sorting
    // by alias, the tests also verify that a proper exception is thrown.
    sql("select distinct cast(empno as bigint) as empno " + "from emp order by ^empno^").failsIf(!tester.getConformance().isSortByAlias(), "Expression 'EMPNO' is not in the select clause");
    sql("select distinct cast(empno as bigint) as eno " + "from emp order by ^eno^").failsIf(!tester.getConformance().isSortByAlias(), "Column 'ENO' not found in any table");
    sql("select distinct cast(empno as bigint) as empno " + "from emp e order by ^empno^").failsIf(!tester.getConformance().isSortByAlias(), "Expression 'EMPNO' is not in the select clause");
    // Distinct on expressions, sorting using ordinals.
    if (tester.getConformance().isSortByOrdinal()) {
        check("select distinct cast(empno as bigint) from emp order by 1");
        check("select distinct cast(empno as bigint) as empno " + "from emp order by 1");
        check("select distinct cast(empno as bigint) as empno " + "from emp as e order by 1");
    }
    // Distinct on expressions with ordering on expressions as well
    check("select distinct cast(empno as varchar(10)) from emp " + "order by cast(empno as varchar(10))");
    checkFails("select distinct cast(empno as varchar(10)) as eno from emp " + " order by upper(^eno^)", tester.getConformance().isSortByAlias() ? null : "Column 'ENO' not found in any table");
}

/**
 * Tests validation of the ORDER BY clause when DISTINCT and GROUP BY are
 * present.
 *
 * <p>Test case for
 * <a href="https://issues.apache.org/jira/browse/CALCITE-634">[CALCITE-634]
 * Allow ORDER BY aggregate function in SELECT DISTINCT, provided that it
 * occurs in SELECT clause</a>.
 */
@Test
public void testOrderGroupDistinct() {
    // Order by an aggregate function,
    // which exists in select-clause with distinct being present
    check("select distinct count(empno) AS countEMPNO from emp\n" + "group by empno\n" + "order by 1");
    check("select distinct count(empno) from emp\n" + "group by empno\n" + "order by 1");
    check("select distinct count(empno) AS countEMPNO from emp\n" + "group by empno\n" + "order by count(empno)");
    check("select distinct count(empno) from emp\n" + "group by empno\n" + "order by count(empno)");
    check("select distinct count(empno) from emp\n" + "group by empno\n" + "order by count(empno) desc");
    checkFails("SELECT DISTINCT deptno from emp\n" + "ORDER BY deptno, ^sum(empno)^", "Aggregate expression is illegal in ORDER BY clause of non-aggregating SELECT");
    checkFails("SELECT DISTINCT deptno from emp\n" + "GROUP BY deptno ORDER BY deptno, ^sum(empno)^", "Expression 'SUM\\(`EMPNO`\\)' is not in the select clause");
    checkFails("SELECT DISTINCT deptno, min(empno) from emp\n" + "GROUP BY deptno ORDER BY deptno, ^sum(empno)^", "Expression 'SUM\\(`EMPNO`\\)' is not in the select clause");
    check("SELECT DISTINCT deptno, sum(empno) from emp\n" + "GROUP BY deptno ORDER BY deptno, sum(empno)");
}

@Test
public void testGroup() {
    checkFails("select empno from emp where ^sum(sal)^ > 50", "Aggregate expression is illegal in WHERE clause");
    checkFails("select ^empno^ from emp group by deptno", "Expression 'EMPNO' is not being grouped");
    checkFails("select ^*^ from emp group by deptno", "Expression 'EMP\\.EMPNO' is not being grouped");
    // If we're grouping on ALL columns, 'select *' is ok.
    // Checked on Oracle10G.
    check("select * from (select empno,deptno from emp) group by deptno,empno");
    // This query tries to reference an agg expression from within a
    // sub-query as a correlating expression, but the SQL syntax rules say
    // that the agg function SUM always applies to the current scope.
    // As it happens, the query is valid.
    check("select deptno\n" + "from emp\n" + "group by deptno\n" + "having exists (select sum(emp.sal) > 10 from (values(true)))");
    // if you reference a column from a sub-query, it must be a group col
    check("select deptno " + "from emp " + "group by deptno " + "having exists (select 1 from (values(true)) where emp.deptno = 10)");
    // Needs proper error message text and error markers in query
    if (TODO) {
        checkFails("select deptno " + "from emp " + "group by deptno " + "having exists (select 1 from (values(true)) where emp.empno = 10)", "xx");
    }
    // constant expressions
    check("select cast(1 as integer) + 2 from emp group by deptno");
    check("select localtime, deptno + 3 from emp group by deptno");
}

