    sql("select deptno, count(*) as c, sum(sal) as s\n" + "from emp\n" + "group by rollup(deptno)").ok().type("RecordType(INTEGER DEPTNO, BIGINT NOT NULL C, INTEGER NOT NULL S) NOT NULL");
    // EMPNO stays NOT NULL because it is not rolled up
    sql("select deptno, empno\n" + "from emp\n" + "group by empno, rollup(deptno)").ok().type("RecordType(INTEGER DEPTNO, INTEGER NOT NULL EMPNO) NOT NULL");
