    if (Bug.FRG78_FIXED) {
        checkFails("select case ^empno^ when 10 then 'foo bar' collate latin1$en$1 else null end from emp " + "group by case empno when 10 then 'foo bar' collate latin1$fr$1 else null end", "Expression 'EMPNO' is not being grouped");
    }
}

