    sql("select sum(max(empno)) OVER w
" + " from emp
" + " window w as (order by ^deptno^ ROWS 2 PRECEDING)").fails("Expression 'DEPTNO' is not being grouped");
    sql("select sum(max(empno)) OVER w2, sum(deptno) OVER w1
" + " from emp group by deptno
" + " window w1 as (partition by ^empno^ ROWS 2 PRECEDING),
