    sql("select avg(deptno) OVER (order by ^empno^),
" + " avg(count(empno)) OVER (partition by deptno)
" + " from emp group by deptno").fails("Expression 'EMPNO' is not being grouped");
    sql("select avg(sum(sal)) OVER (partition by ^empno^)
" + " from emp").fails("Expression 'EMPNO' is not being grouped");
    sql("select avg(sum(sal)) OVER (partition by ^empno^)
" + "from emp group by deptno").fails("Expression 'EMPNO' is not being grouped");
    sql("select avg(sum(sal)) OVER (partition by ^empno^)
" + " from emp").fails("Expression 'EMPNO' is not being grouped");
    sql("select avg(sum(sal)) OVER (partition by ^empno^)
" + "from emp group by deptno").fails("Expression 'EMPNO' is not being grouped");
    sql("select avg(sum(sal)) OVER (partition by deptno order by ^empno^)
" + "from emp group by deptno").fails("Expression 'EMPNO' is not being grouped");
    sql("select avg(^sal^) OVER (),
" + " avg(count(empno)) OVER (partition by min(deptno))
" + " from emp").fails("Expression 'SAL' is not being grouped");
    check("select avg(deptno) OVER (),
" + " avg(count(empno)) OVER (partition by deptno)" + " from emp group by deptno");
    // COUNT(*), PARTITION BY(CONST) with GROUP BY is OK
    check("select avg(count(*)) OVER ()
" + " from emp group by deptno");
    check("select count(*) OVER ()
" + " from emp group by deptno");
    check("select count(deptno) OVER ()
" + " from emp group by deptno");
    check("select count(deptno, deptno + 1) OVER ()
" + " from emp group by deptno");
    sql("select count(deptno, deptno + 1, ^empno^) OVER ()
" + " from emp group by deptno").fails("Expression 'EMPNO' is not being grouped");
    sql("select count(emp.^*^)
" + "from emp group by deptno").fails("Unknown field '\*'");
    sql("select count(emp.^*^) OVER ()
" + "from emp group by deptno").fails("Unknown field '\*'");
    check("select avg(count(*)) OVER (partition by 1)
" + " from emp group by deptno");
    check("select avg(sum(sal)) OVER (partition by 1)
" + " from emp");
    check("select avg(sal), avg(count(empno)) OVER (partition by 1)
" + " from emp");
    // expression is OK
    check("select avg(sum(sal)) OVER (partition by 10 - deptno
" + "   order by deptno / 2 desc)
" + "from emp group by deptno");
    check("select avg(sal),
" + " avg(count(empno)) OVER (partition by min(deptno))
" + " from emp");
    check("select avg(min(sal)) OVER (),
