" + " from emp");
    // expression involving non-GROUP column is not OK
    sql("select avg(2+^sal^) OVER (partition by deptno)
" + "from emp group by deptno").fails("Expression 'SAL' is not being grouped");
    sql("select avg(sum(sal)) OVER (partition by deptno + ^empno^)
