    // expression is NOT OK (AS clause)
    sql("select sum(max(empno))
" + " OVER (order by ^deptno^ ROWS 2 PRECEDING) AS sumEmpNo
" + " from emp").fails("Expression 'DEPTNO' is not being grouped");
    sql("select sum(max(empno)) OVER w AS sumEmpNo
" + " from emp
" + " window w AS (order by ^deptno^ ROWS 2 PRECEDING)").fails("Expression 'DEPTNO' is not being grouped");
    sql("select avg(^sal^) OVER () AS avgSal," + " avg(count(empno)) OVER (partition by 1) AS avgEmpNo
" + " from emp").fails("Expression 'SAL' is not being grouped");
    sql("select count(deptno, deptno + 1, ^empno^) OVER () AS cntDeptEmp
" + " from emp group by deptno").fails("Expression 'EMPNO' is not being grouped");
    sql("select avg(sum(sal)) OVER (partition by ^deptno^ + 1) AS avgSal
" + "from emp group by empno + deptno").fails("Expression 'DEPTNO' is not being grouped");
