public void testOverlaps() {
    checkExpType("(date '1-2-3', date '1-2-3')\n" + " overlaps (date '1-2-3', date '1-2-3')", "BOOLEAN NOT NULL");
    checkExpType("period (date '1-2-3', date '1-2-3')\n" + " overlaps period (date '1-2-3', date '1-2-3')", "BOOLEAN NOT NULL");
    checkExp("(date '1-2-3', date '1-2-3') overlaps (date '1-2-3', interval '1' year)");
    checkExp("(time '1:2:3', interval '1' second) overlaps (time '23:59:59', time '1:2:3')");
    checkExp("(timestamp '1-2-3 4:5:6', timestamp '1-2-3 4:5:6' ) overlaps (timestamp '1-2-3 4:5:6', interval '1 2:3:4.5' day to second)");
    checkWholeExpFails("(timestamp '1-2-3 4:5:6', timestamp '1-2-3 4:5:6' ) overlaps (time '4:5:6', interval '1 2:3:4.5' day to second)", "(?s).*Cannot apply 'OVERLAPS' to arguments of type .*");
    checkWholeExpFails("(time '4:5:6', timestamp '1-2-3 4:5:6' ) overlaps (time '4:5:6', interval '1 2:3:4.5' day to second)", "(?s).*Cannot apply 'OVERLAPS' to arguments of type .*");
    checkWholeExpFails("(time '4:5:6', time '4:5:6' ) overlaps (time '4:5:6', date '1-2-3')", "(?s).*Cannot apply 'OVERLAPS' to arguments of type .*");
    checkWholeExpFails("1 overlaps 2", "(?s).*Cannot apply 'OVERLAPS' to arguments of type " + "'<INTEGER> OVERLAPS <INTEGER>'\\. Supported form.*");
    checkExpType("true\n" + "or (date '1-2-3', date '1-2-3')\n" + "   overlaps (date '1-2-3', date '1-2-3')\n" + "or false", "BOOLEAN NOT NULL");
    // row with 3 arguments as left argument to overlaps
    checkExpFails("true\n" + "or ^(date '1-2-3', date '1-2-3', date '1-2-3')\n" + "   overlaps (date '1-2-3', date '1-2-3')^\n" + "or false", "(?s).*Cannot apply 'OVERLAPS' to arguments of type .*");
    // row with 3 arguments as right argument to overlaps
    checkExpFails("true\n" + "or ^(date '1-2-3', date '1-2-3')\n" + "  overlaps (date '1-2-3', date '1-2-3', date '1-2-3')^\n" + "or false", "(?s).*Cannot apply 'OVERLAPS' to arguments of type .*");
    checkExpFails("^period (date '1-2-3', date '1-2-3')\n" + "   overlaps (date '1-2-3', date '1-2-3', date '1-2-3')^", "(?s).*Cannot apply 'OVERLAPS' to arguments of type .*");
    checkExpFails("true\n" + "or ^(1, 2) overlaps (2, 3)^\n" + "or false", "(?s).*Cannot apply 'OVERLAPS' to arguments of type .*");
    // Other operators with similar syntax
    String[] ops = { "overlaps", "contains", "equals", "precedes", "succeeds", "immediately precedes", "immediately succeeds" };
    for (String op : ops) {
        checkExpType("period (date '1-2-3', date '1-2-3')\n" + " " + op + " period (date '1-2-3', date '1-2-3')", "BOOLEAN NOT NULL");
        checkExpType("(date '1-2-3', date '1-2-3')\n" + " " + op + " (date '1-2-3', date '1-2-3')", "BOOLEAN NOT NULL");
    }
}

@Test
public void testContains() {
    final String cannotApply = "(?s).*Cannot apply 'CONTAINS' to arguments of type .*";
    checkExpType("(date '1-2-3', date '1-2-3')\n" + " contains (date '1-2-3', date '1-2-3')", "BOOLEAN NOT NULL");
    checkExpType("period (date '1-2-3', date '1-2-3')\n" + " contains period (date '1-2-3', date '1-2-3')", "BOOLEAN NOT NULL");
    checkExp("(date '1-2-3', date '1-2-3')\n" + "  contains (date '1-2-3', interval '1' year)");
    checkExp("(time '1:2:3', interval '1' second)\n" + " contains (time '23:59:59', time '1:2:3')");
    checkExp("(timestamp '1-2-3 4:5:6', timestamp '1-2-3 4:5:6')\n" + " contains (timestamp '1-2-3 4:5:6', interval '1 2:3:4.5' day to second)");
    // period contains point
    checkExp("(date '1-2-3', date '1-2-3')\n" + "  contains date '1-2-3'");
    // same, with "period" keyword
    checkExp("period (date '1-2-3', date '1-2-3')\n" + "  contains date '1-2-3'");
    // point contains period
    checkWholeExpFails("date '1-2-3'\n" + "  contains (date '1-2-3', date '1-2-3')", cannotApply);
    // same, with "period" keyword
    checkWholeExpFails("date '1-2-3'\n" + "  contains period (date '1-2-3', date '1-2-3')", cannotApply);
    // point contains point
    checkWholeExpFails("date '1-2-3' contains date '1-2-3'", cannotApply);
    checkWholeExpFails("(timestamp '1-2-3 4:5:6', timestamp '1-2-3 4:5:6' )\n" + " contains (time '4:5:6', interval '1 2:3:4.5' day to second)", cannotApply);
    checkWholeExpFails("(time '4:5:6', timestamp '1-2-3 4:5:6' )\n" + " contains (time '4:5:6', interval '1 2:3:4.5' day to second)", cannotApply);
    checkWholeExpFails("(time '4:5:6', time '4:5:6' )\n" + "  contains (time '4:5:6', date '1-2-3')", cannotApply);
    checkWholeExpFails("1 contains 2", cannotApply);
    // row with 3 arguments
    checkExpFails("true\n" + "or ^(date '1-2-3', date '1-2-3', date '1-2-3')\n" + "  contains (date '1-2-3', date '1-2-3')^\n" + "or false", cannotApply);
    checkExpType("true\n" + "or (date '1-2-3', date '1-2-3')\n" + "  contains (date '1-2-3', date '1-2-3')\n" + "or false", "BOOLEAN NOT NULL");
    // second argument is a point
    checkExpType("true\n" + "or (date '1-2-3', date '1-2-3')\n" + "  contains date '1-2-3'\n" + "or false", "BOOLEAN NOT NULL");
    // first argument may be null, so result may be null
    checkExpType("true\n" + "or (date '1-2-3',\n" + "     case 1 when 2 then date '1-2-3' else null end)\n" + "  contains date '1-2-3'\n" + "or false", "BOOLEAN");
    // second argument may be null, so result may be null
    checkExpType("true\n" + "or (date '1-2-3', date '1-2-3')\n" + "  contains case 1 when 1 then date '1-2-3' else null end\n" + "or false", "BOOLEAN");
    checkExpFails("true\n" + "or ^period (date '1-2-3', date '1-2-3')\n" + "  contains period (date '1-2-3', time '4:5:6')^\n" + "or false", cannotApply);
    checkExpFails("true\n" + "or ^(1, 2) contains (2, 3)^\n" + "or false", cannotApply);
}

