@Test
public void testUnnestArrayColumn() {
    final String sql1 = "select d.deptno, e.*\n" + "from dept_nested as d,\n" + " UNNEST(d.employees) as e";
    final String type = "RecordType(INTEGER NOT NULL DEPTNO," + " INTEGER NOT NULL EMPNO," + " VARCHAR(10) NOT NULL ENAME," + " RecordType(RecordType(VARCHAR(10) NOT NULL TYPE, VARCHAR(20) NOT NULL DESC," + " RecordType(VARCHAR(10) NOT NULL A, VARCHAR(10) NOT NULL B) NOT NULL OTHERS)" + " NOT NULL ARRAY NOT NULL SKILLS) NOT NULL DETAIL) NOT NULL";
    sql(sql1).type(type);
    // equivalent query without table alias
    final String sql1b = "select d.deptno, e.*\n" + "from dept_nested as d,\n" + " UNNEST(employees) as e";
    sql(sql1b).type(type);
    // equivalent query using CROSS JOIN
    final String sql2 = "select d.deptno, e.*\n" + "from dept_nested as d CROSS JOIN\n" + " UNNEST(d.employees) as e";
    sql(sql2).type(type);
    // equivalent query using CROSS JOIN, without table alias
    final String sql2b = "select d.deptno, e.*\n" + "from dept_nested as d CROSS JOIN\n" + " UNNEST(employees) as e";
    sql(sql2b).type(type);
    // LATERAL works left-to-right
    final String sql3 = "select d.deptno, e.*\n" + "from UNNEST(^d^.employees) as e, dept_nested as d";
    sql(sql3).fails("Table 'D' not found");
}

