@Test
public void testSelectDistinct() {
    check("SELECT DISTINCT deptno FROM emp");
    check("SELECT DISTINCT deptno, sal FROM emp");
    check("SELECT DISTINCT deptno FROM emp GROUP BY deptno");
    checkFails("SELECT DISTINCT ^deptno^ FROM emp GROUP BY sal", "Expression 'DEPTNO' is not being grouped");
    check("SELECT DISTINCT avg(sal) from emp");
    checkFails("SELECT DISTINCT ^deptno^, avg(sal) from emp", "Expression 'DEPTNO' is not being grouped");
    check("SELECT DISTINCT deptno, sal from emp GROUP BY sal, deptno");
    check("SELECT deptno FROM emp GROUP BY deptno HAVING deptno > 55");
    check("SELECT DISTINCT deptno, 33 FROM emp\n" + "GROUP BY deptno HAVING deptno > 55");
    sql("SELECT DISTINCT deptno, 33 FROM emp HAVING ^deptno^ > 55").fails("Expression 'DEPTNO' is not being grouped");
    // same query under a different conformance finds a different error first
    sql("SELECT DISTINCT ^deptno^, 33 FROM emp HAVING deptno > 55").tester(tester.withConformance(SqlConformanceEnum.LENIENT)).fails("Expression 'DEPTNO' is not being grouped");
    sql("SELECT DISTINCT 33 FROM emp HAVING ^deptno^ > 55").fails("Expression 'DEPTNO' is not being grouped").tester(tester.withConformance(SqlConformanceEnum.LENIENT)).fails("Expression 'DEPTNO' is not being grouped");
    check("SELECT DISTINCT * from emp");
    checkFails("SELECT DISTINCT ^*^ from emp GROUP BY deptno", "Expression 'EMP\\.EMPNO' is not being grouped");
    // similar validation for SELECT DISTINCT and GROUP BY
    checkFails("SELECT deptno FROM emp GROUP BY deptno ORDER BY deptno, ^empno^", "Expression 'EMPNO' is not being grouped");
    checkFails("SELECT DISTINCT deptno from emp ORDER BY deptno, ^empno^", "Expression 'EMPNO' is not in the select clause");
    check("SELECT DISTINCT deptno from emp ORDER BY deptno + 2");
    // The ORDER BY clause works on what is projected by DISTINCT - even if
    // GROUP BY is present.
    checkFails("SELECT DISTINCT deptno FROM emp GROUP BY deptno, empno ORDER BY deptno, ^empno^", "Expression 'EMPNO' is not in the select clause");
    // redundant distinct; same query is in unitsql/optimizer/distinct.sql
    check("select distinct * from (\n" + "  select distinct deptno from emp) order by 1");
    check("SELECT DISTINCT 5, 10+5, 'string' from emp");
}

