@Test
public void testSelectAmbiguousField() {
    tester = tester.withCaseSensitive(false).withUnquotedCasing(Casing.UNCHANGED);
    sql("select ^t0^ from (select 1 as t0, 2 as T0 from dept)").fails("Column 't0' is ambiguous");
    sql("select ^t0^ from (select 1 as t0, 2 as t0,3 as t1,4 as t1, 5 as t2 from dept)").fails("Column 't0' is ambiguous");
    // t0 is not referenced,so this case is allowed
    sql("select 1 as t0, 2 as t0 from dept").ok();
    tester = tester.withCaseSensitive(true).withUnquotedCasing(Casing.UNCHANGED);
    sql("select t0 from (select 1 as t0, 2 as T0 from DEPT)").ok();
}

