/**
 * Test case for
 * <a href="https://issues.apache.org/jira/browse/CALCITE-497">[CALCITE-497]
 * Support optional qualifier for column name references</a>.
 */
@Test
public void testRecordTypeElided() {
    sql("SELECT contact.^x^, contact.coord.y FROM customer.contact").fails("Column 'X' not found in table 'CONTACT'");
    // Fully qualified works.
    sql("SELECT contact.coord.x, contact.coord.y FROM customer.contact").type("RecordType(INTEGER NOT NULL X, INTEGER NOT NULL Y) NOT NULL");
    // Because the types of CONTACT_PEEK.COORD and CONTACT_PEEK.COORD_NE are
    // marked "peek", the validator can see through them.
    sql("SELECT c.x, c.coord.y, c.m, c.b FROM customer.contact_peek as c").type("RecordType(INTEGER NOT NULL X, INTEGER NOT NULL Y, INTEGER NOT NULL M," + " INTEGER NOT NULL B) NOT NULL");
    sql("SELECT c.coord.x, c.coord.y, c.coord_ne.m FROM customer.contact_peek as c").type("RecordType(INTEGER NOT NULL X, INTEGER NOT NULL Y, INTEGER NOT NULL M) NOT NULL");
    sql("SELECT x, a, c.coord.y FROM customer.contact_peek as c").type("RecordType(INTEGER NOT NULL X, INTEGER NOT NULL A, INTEGER NOT NULL Y) NOT NULL");
    // Because CONTACT_PEEK.COORD_NE is marked "peek no expand",
    // "select *" does not flatten it.
    sql("SELECT coord_ne.* FROM customer.contact_peek as c").type("RecordType(INTEGER NOT NULL M, " + "RecordType:peek_no_expand(INTEGER NOT NULL A, INTEGER NOT NULL B) " + "NOT NULL SUB) NOT NULL");
    sql("SELECT * FROM customer.contact_peek as c").type("RecordType(INTEGER NOT NULL CONTACTNO, VARCHAR(10) NOT NULL FNAME, " + "VARCHAR(10) NOT NULL LNAME, VARCHAR(20) NOT NULL EMAIL, INTEGER NOT NULL X, " + "INTEGER NOT NULL Y, VARCHAR(20) NOT NULL unit, " + "RecordType:peek_no_expand(INTEGER NOT NULL M, " + "RecordType:peek_no_expand(INTEGER NOT NULL A, INTEGER NOT NULL B) " + "NOT NULL SUB) NOT NULL COORD_NE) NOT NULL");
    // Qualifying with schema is OK.
    final String sql = "SELECT customer.contact_peek.x,\n" + " customer.contact_peek.email, contact_peek.coord.y\n" + "FROM customer.contact_peek";
    sql(sql).type("RecordType(INTEGER NOT NULL X, VARCHAR(20) NOT NULL EMAIL," + " INTEGER NOT NULL Y) NOT NULL");
}

@Test
public void testSample() {
    // applied to table
    check("SELECT * FROM emp TABLESAMPLE SUBSTITUTE('foo')");
    check("SELECT * FROM emp TABLESAMPLE BERNOULLI(50)");
    check("SELECT * FROM emp TABLESAMPLE SYSTEM(50)");
    // applied to query
    check("SELECT * FROM (" + "SELECT deptno FROM emp " + "UNION ALL " + "SELECT deptno FROM dept) AS x TABLESAMPLE SUBSTITUTE('foo') " + "WHERE x.deptno < 100");
    checkFails("SELECT x.^empno^ FROM (" + "SELECT deptno FROM emp TABLESAMPLE SUBSTITUTE('bar') " + "UNION ALL " + "SELECT deptno FROM dept) AS x TABLESAMPLE SUBSTITUTE('foo') " + "ORDER BY 1", "Column 'EMPNO' not found in table 'X'");
    check("select * from (\n" + "    select * from emp\n" + "    join dept on emp.deptno = dept.deptno\n" + ") tablesample substitute('SMALL')");
    check("SELECT * FROM (" + "SELECT deptno FROM emp " + "UNION ALL " + "SELECT deptno FROM dept) AS x TABLESAMPLE BERNOULLI(50) " + "WHERE x.deptno < 100");
    checkFails("SELECT x.^empno^ FROM (" + "SELECT deptno FROM emp TABLESAMPLE BERNOULLI(50) " + "UNION ALL " + "SELECT deptno FROM dept) AS x TABLESAMPLE BERNOULLI(10) " + "ORDER BY 1", "Column 'EMPNO' not found in table 'X'");
    check("select * from (\n" + "    select * from emp\n" + "    join dept on emp.deptno = dept.deptno\n" + ") tablesample bernoulli(10)");
    check("SELECT * FROM (" + "SELECT deptno FROM emp " + "UNION ALL " + "SELECT deptno FROM dept) AS x TABLESAMPLE SYSTEM(50) " + "WHERE x.deptno < 100");
    checkFails("SELECT x.^empno^ FROM (" + "SELECT deptno FROM emp TABLESAMPLE SYSTEM(50) " + "UNION ALL " + "SELECT deptno FROM dept) AS x TABLESAMPLE SYSTEM(10) " + "ORDER BY 1", "Column 'EMPNO' not found in table 'X'");
    check("select * from (\n" + "    select * from emp\n" + "    join dept on emp.deptno = dept.deptno\n" + ") tablesample system(10)");
}

