/**
 * Test case for
 * <a href="https://issues.apache.org/jira/browse/CALCITE-1549">[CALCITE-1549]
 * Improve error message when table or column not found</a>.
 */
@Test
public void testTableNotFoundDidYouMean() {
    // No table in default schema
    tester.checkQueryFails("select * from ^unknownTable^", "Object 'UNKNOWNTABLE' not found");
    // Similar table exists in default schema
    tester.checkQueryFails("select * from ^\"Emp\"^", "Object 'Emp' not found within 'SALES'; did you mean 'EMP'\\?");
    // Schema correct, but no table in specified schema
    tester.checkQueryFails("select * from ^sales.unknownTable^", "Object 'UNKNOWNTABLE' not found within 'SALES'");
    // Similar table exists in specified schema
    tester.checkQueryFails("select * from ^sales.\"Emp\"^", "Object 'Emp' not found within 'SALES'; did you mean 'EMP'\\?");
    // No schema found
    tester.checkQueryFails("select * from ^unknownSchema.unknownTable^", "Object 'UNKNOWNSCHEMA' not found");
    // Similar schema found
    tester.checkQueryFails("select * from ^\"sales\".emp^", "Object 'sales' not found; did you mean 'SALES'\\?");
    tester.checkQueryFails("select * from ^\"saLes\".\"eMp\"^", "Object 'saLes' not found; did you mean 'SALES'\\?");
    // Spurious after table
    tester.checkQueryFails("select * from ^emp.foo^", "Object 'FOO' not found within 'SALES\\.EMP'");
    tester.checkQueryFails("select * from ^sales.emp.foo^", "Object 'FOO' not found within 'SALES\\.EMP'");
    // Alias not found
    tester.checkQueryFails("select ^aliAs^.\"name\"\n" + "from sales.emp as \"Alias\"", "Table 'ALIAS' not found; did you mean 'Alias'\\?");
    // Alias not found, fully-qualified
    tester.checkQueryFails("select ^sales.\"emp\"^.\"name\" from sales.emp", "Table 'SALES\\.emp' not found; did you mean 'EMP'\\?");
}

@Test
public void testColumnNotFoundDidYouMean() {
    // Column not found
    tester.checkQueryFails("select ^\"unknownColumn\"^ from emp", "Column 'unknownColumn' not found in any table");
    // Similar column in table, unqualified table name
    tester.checkQueryFails("select ^\"empNo\"^ from emp", "Column 'empNo' not found in any table; did you mean 'EMPNO'\\?");
    // Similar column in table, table name qualified with schema
    tester.checkQueryFails("select ^\"empNo\"^ from sales.emp", "Column 'empNo' not found in any table; did you mean 'EMPNO'\\?");
    // Similar column in table, table name qualified with catalog and schema
    tester.checkQueryFails("select ^\"empNo\"^ from catalog.sales.emp", "Column 'empNo' not found in any table; did you mean 'EMPNO'\\?");
    // With table alias
    tester.checkQueryFails("select e.^\"empNo\"^ from catalog.sales.emp as e", "Column 'empNo' not found in table 'E'; did you mean 'EMPNO'\\?");
    // With fully-qualified table alias
    tester.checkQueryFails("select catalog.sales.emp.^\"empNo\"^\n" + "from catalog.sales.emp", "Column 'empNo' not found in table 'CATALOG\\.SALES\\.EMP'; " + "did you mean 'EMPNO'\\?");
    // Similar column in table; multiple tables
    tester.checkQueryFails("select ^\"name\"^ from emp, dept", "Column 'name' not found in any table; did you mean 'NAME'\\?");
    // Similar column in table; table and a query
    tester.checkQueryFails("select ^\"name\"^ from emp,\n" + "  (select * from dept) as d", "Column 'name' not found in any table; did you mean 'NAME'\\?");
    // Similar column in table; table and an un-aliased query
    tester.checkQueryFails("select ^\"name\"^ from emp, (select * from dept)", "Column 'name' not found in any table; did you mean 'NAME'\\?");
    // Similar column in table, multiple tables
    tester.checkQueryFails("select ^\"deptno\"^ from emp,\n" + "  (select deptno as \"deptNo\" from dept)", "Column 'deptno' not found in any table; " + "did you mean 'DEPTNO', 'deptNo'\\?");
    tester.checkQueryFails("select ^\"deptno\"^ from emp,\n" + "  (select * from dept) as t(\"deptNo\", name)", "Column 'deptno' not found in any table; " + "did you mean 'DEPTNO', 'deptNo'\\?");
}

/**
 * Tests matching of built-in operator names.
 */
@Test
public void testUnquotedBuiltInFunctionNames() {
    final SqlTester mysql = tester.withUnquotedCasing(Casing.UNCHANGED).withQuoting(Quoting.BACK_TICK).withCaseSensitive(false);
    final SqlTester oracle = tester.withUnquotedCasing(Casing.TO_UPPER).withCaseSensitive(true);
    // Built-in functions are always case-insensitive.
    oracle.checkQuery("select count(*), sum(deptno), floor(2.5) from dept");
    oracle.checkQuery("select COUNT(*), FLOOR(2.5) from dept");
    oracle.checkQuery("select cOuNt(*), FlOOr(2.5) from dept");
    oracle.checkQuery("select cOuNt (*), FlOOr (2.5) from dept");
    oracle.checkQuery("select current_time from dept");
    oracle.checkQuery("select Current_Time from dept");
    oracle.checkQuery("select CURRENT_TIME from dept");
    mysql.checkQuery("select sum(deptno), floor(2.5) from dept");
    mysql.checkQuery("select count(*), sum(deptno), floor(2.5) from dept");
    mysql.checkQuery("select COUNT(*), FLOOR(2.5) from dept");
    mysql.checkQuery("select cOuNt(*), FlOOr(2.5) from dept");
    mysql.checkQuery("select cOuNt (*), FlOOr (2.5) from dept");
    mysql.checkQuery("select current_time from dept");
    mysql.checkQuery("select Current_Time from dept");
    mysql.checkQuery("select CURRENT_TIME from dept");
    // MySQL assumes that a quoted function name is not a built-in.
    //
    // mysql> select `sum`(`day`) from days;
    // ERROR 1630 (42000): FUNCTION foodmart.sum does not exist. Check the
    //   'Function Name Parsing and Resolution' section in the Reference Manual
    // mysql> select `SUM`(`day`) from days;
    // ERROR 1630 (42000): FUNCTION foodmart.SUM does not exist. Check the
    //   'Function Name Parsing and Resolution' section in the Reference Manual
    // mysql> select SUM(`day`) from days;
    // +------------+
    // | SUM(`day`) |
    // +------------+
    // |         28 |
    // +------------+
    // 1 row in set (0.00 sec)
    //
    // We do not follow MySQL in this regard. `count` is preserved in
    // lower-case, and is matched case-insensitively because it is a built-in.
    // So, the query succeeds.
    oracle.checkQuery("select \"count\"(*) from dept");
    mysql.checkQuery("select `count`(*) from dept");
}

/**
 * Sanity check: All built-ins are upper-case. We rely on this.
 */
@Test
public void testStandardOperatorNamesAreUpperCase() {
    for (SqlOperator op : SqlStdOperatorTable.instance().getOperatorList()) {
        final String name = op.getName();
        switch(op.getSyntax()) {
            case SPECIAL:
            case INTERNAL:
                break;
            default:
                assertThat(name.toUpperCase(Locale.ROOT), equalTo(name));
                break;
        }
    }
}

