    sql("insert into empnullables (ename, empno) values (?, ? + 1)").ok().bindType("RecordType(VARCHAR(20) ?0, INTEGER ?1)");
    // SELECT
    sql("insert into empnullables (ename, empno) select ?, ? from (values (1))").ok().bindType("RecordType(VARCHAR(20) ?0, INTEGER ?1)");
    // WITH
    final String sql3 = "insert into empnullables (ename, empno)\n" + "with v as (values ('a'))\n" + "select ?, ? from (values (1))";
    sql(sql3).ok().bindType("RecordType(VARCHAR(20) ?0, INTEGER ?1)");
    // UNION
    final String sql2 = "insert into empnullables (ename, empno)\n" + "select ?, ? from (values (1))\n" + "union all\n" + "select ?, ? from (values (time '1:2:3'))";
