    sql("select stream *
" + "from orders
" + "order by rowtime").ok();
    sql("select stream *
" + "from orders
" + "order by floor(rowtime to hour)").ok();
    sql("select stream floor(rowtime to minute), productId
" + "from orders
" + "order by floor(rowtime to hour)").ok();
    sql("select stream floor(rowtime to minute), productId
" + "from orders
" + "order by floor(rowtime to minute), productId desc").ok();
    sql("select stream *
" + "from orders
" + "order by ^productId^, rowtime").fails(STR_ORDER_REQUIRES_MONO);
    sql("select stream *
" + "from orders
" + "order by ^rowtime desc^").fails(STR_ORDER_REQUIRES_MONO);
    sql("select stream *
" + "from orders
" + "order by floor(rowtime to hour), rowtime desc").ok();
}

@Test
