    sql("select stream \n" + "orders.rowtime as rowtime, orders.orderId as orderId, products.supplierId as supplierId \n" + "from orders join products on orders.productId = products.productId").ok();
    sql("^select stream *\n" + "from products join suppliers on products.supplierId = suppliers.supplierId^").fails(cannotStreamResultsForNonStreamingInputs("PRODUCTS, SUPPLIERS"));
}

