@Test
public void testStreamTumble() {
    // TUMBLE
    sql("select stream tumble_end(rowtime, interval '2' hour) as rowtime
" + "from orders
" + "group by tumble(rowtime, interval '2' hour), productId").ok();
    sql("select stream ^tumble(rowtime, interval '2' hour)^ as rowtime
" + "from orders
" + "group by tumble(rowtime, interval '2' hour), productId").fails("Group function 'TUMBLE' can only appear in GROUP BY clause");
    // TUMBLE with align argument
    sql("select stream
" + "  tumble_end(rowtime, interval '2' hour, time '00:12:00') as rowtime
" + "from orders
" + "group by tumble(rowtime, interval '2' hour, time '00:12:00')").ok();
    // TUMBLE_END without corresponding TUMBLE
    sql("select stream
" + "  ^tumble_end(rowtime, interval '2' hour, time '00:13:00')^ as rowtime
" + "from orders
" + "group by floor(rowtime to hour)").fails("Call to auxiliary group function 'TUMBLE_END' must have " + "matching call to group function 'TUMBLE' in GROUP BY clause");
    // Arguments to TUMBLE_END are slightly different to arguments to TUMBLE
    sql("select stream
" + "  ^tumble_start(rowtime, interval '2' hour, time '00:13:00')^ as rowtime
" + "from orders
" + "group by tumble(rowtime, interval '2' hour, time '00:12:00')").fails("Call to auxiliary group function 'TUMBLE_START' must have " + "matching call to group function 'TUMBLE' in GROUP BY clause");
    // Even though align defaults to TIME '00:00:00', we need structural
    // equivalence, not semantic equivalence.
    sql("select stream
" + "  ^tumble_end(rowtime, interval '2' hour, time '00:00:00')^ as rowtime
" + "from orders
" + "group by tumble(rowtime, interval '2' hour)").fails("Call to auxiliary group function 'TUMBLE_END' must have " + "matching call to group function 'TUMBLE' in GROUP BY clause");
    // TUMBLE query produces no monotonic column - OK
    sql("select stream productId
" + "from orders
" + "group by tumble(rowtime, interval '2' hour), productId").ok();
    sql("select stream productId
" + "from orders
" + "^group by productId,
" + "  tumble(timestamp '1990-03-04 12:34:56', interval '2' hour)^").fails(STR_AGG_REQUIRES_MONO);
}

@Test
public void testStreamHop() {
    // HOP
    sql("select stream
" + "  hop_start(rowtime, interval '1' hour, interval '3' hour) as rowtime,
" + "  count(*) as c
" + "from orders
" + "group by hop(rowtime, interval '1' hour, interval '3' hour)").ok();
    sql("select stream
" + "  ^hop_start(rowtime, interval '1' hour, interval '2' hour)^,
" + "  count(*) as c
" + "from orders
" + "group by hop(rowtime, interval '1' hour, interval '3' hour)").fails("Call to auxiliary group function 'HOP_START' must have " + "matching call to group function 'HOP' in GROUP BY clause");
    // HOP with align
    sql("select stream
" + "  hop_start(rowtime, interval '1' hour, interval '3' hour,
" + "    time '12:34:56') as rowtime,
" + "  count(*) as c
" + "from orders
" + "group by hop(rowtime, interval '1' hour, interval '3' hour,
" + "    time '12:34:56')").ok();
}

