@Test(timeout = 10000)
public void testStreamCancel() {
    final String explain = "EnumerableInterpreter\n" + "  BindableTableScan(table=[[INFINITE_STREAMS, ORDERS, (STREAM)]])";
    CalciteAssert.model(STREAM_MODEL).withDefaultSchema(INFINITE_STREAM_SCHEMA_NAME).query("select stream * from orders").explainContains(explain).returns(resultSet -> {
        int n = 0;
        try {
            while (resultSet.next()) {
                if (++n == 5) {
                    new Thread(() -> {
                        try {
                            Thread.sleep(3);
                            resultSet.getStatement().cancel();
                        } catch (InterruptedException | SQLException e) {
                            // ignore
                        }
                    }).start();
                }
            }
            fail("expected cancel, got end-of-data");
        } catch (SQLException e) {
            assertThat(e.getMessage(), is("Statement canceled"));
        }
        // With a 3 millisecond delay, typically n is between 200 - 400
        // before cancel takes effect.
        assertTrue("n is " + n, n > 5);
    });
}

