@Test
public void testPerformance() {
    if (!Benchmark.enabled()) {
        return;
    }
    //noinspection unchecked
    final Iterable<Pair<Function0<List<Integer>>, String>> factories0 = Pair.zip(Arrays.asList(ArrayList::new, LinkedList::new, ChunkList::new), Arrays.asList("ArrayList", "LinkedList", "ChunkList-64"));
    final List<Pair<Function0<List<Integer>>, String>> factories1 = new ArrayList<>();
    for (Pair<Function0<List<Integer>>, String> pair : factories0) {
        factories1.add(pair);
    }
    List<Pair<Function0<List<Integer>>, String>> factories = factories1.subList(2, 3);
    Iterable<Pair<Integer, String>> sizes = Pair.zip(Arrays.asList(100000, 1000000, 10000000), Arrays.asList("100k", "1m", "10m"));
    for (final Pair<Function0<List<Integer>>, String> pair : factories) {
        new Benchmark("add 10m values, " + pair.right, statistician -> {
            final List<Integer> list = pair.left.apply();
            long start = System.currentTimeMillis();
            for (int i = 0; i < 10000000; i++) {
                list.add(1);
            }
            statistician.record(start);
            return null;
        }, 10).run();
    }
    for (final Pair<Function0<List<Integer>>, String> pair : factories) {
        new Benchmark("iterate over 10m values, " + pair.right, statistician -> {
            final List<Integer> list = pair.left.apply();
            list.addAll(Collections.nCopies(10000000, 1));
            long start = System.currentTimeMillis();
            int count = 0;
            for (Integer integer : list) {
                count += integer;
            }
            statistician.record(start);
            assert count == 10000000;
            return null;
        }, 10).run();
    }
    for (final Pair<Function0<List<Integer>>, String> pair : factories) {
        for (final Pair<Integer, String> size : sizes) {
            if (size.left > 1000000) {
                continue;
            }
            new Benchmark("delete 10% of " + size.right + " values, " + pair.right, statistician -> {
                final List<Integer> list = pair.left.apply();
                list.addAll(Collections.nCopies(size.left, 1));
                long start = System.currentTimeMillis();
                int n = 0;
                for (Iterator<Integer> it = list.iterator(); it.hasNext(); ) {
                    Integer integer = it.next();
                    Util.discard(integer);
                    if (n++ % 10 == 0) {
                        it.remove();
                    }
                }
                statistician.record(start);
                return null;
            }, 10).run();
        }
    }
    for (final Pair<Function0<List<Integer>>, String> pair : factories) {
        for (final Pair<Integer, String> size : sizes) {
            if (size.left > 1000000) {
                continue;
            }
            new Benchmark("get from " + size.right + " values, " + (size.left / 1000) + " times, " + pair.right, statistician -> {
                final List<Integer> list = pair.left.apply();
                list.addAll(Collections.nCopies(size.left, 1));
                final int probeCount = size.left / 1000;
                final Random random = new Random(1);
                long start = System.currentTimeMillis();
                int n = 0;
                for (int i = 0; i < probeCount; i++) {
                    n += list.get(random.nextInt(list.size()));
                }
                assert n == probeCount;
                statistician.record(start);
                return null;
            }, 10).run();
        }
    }
    for (final Pair<Function0<List<Integer>>, String> pair : factories) {
        for (final Pair<Integer, String> size : sizes) {
            if (size.left > 1000000) {
                continue;
            }
            new Benchmark("add " + size.right + " values, delete 10%, insert 20%, get 1%, using " + pair.right, statistician -> {
                final List<Integer> list = pair.left.apply();
                final int probeCount = size.left / 100;
                long start = System.currentTimeMillis();
                list.addAll(Collections.nCopies(size.left, 1));
                final Random random = new Random(1);
                for (Iterator<Integer> it = list.iterator(); it.hasNext(); ) {
                    Integer integer = it.next();
                    Util.discard(integer);
                    if (random.nextInt(10) == 0) {
                        it.remove();
                    }
                }
                for (ListIterator<Integer> it = list.listIterator(); it.hasNext(); ) {
                    Integer integer = it.next();
                    Util.discard(integer);
                    if (random.nextInt(5) == 0) {
                        it.add(2);
                    }
                }
                int n = 0;
                for (int i = 0; i < probeCount; i++) {
                    n += list.get(random.nextInt(list.size()));
                }
                assert n > probeCount;
                statistician.record(start);
                return null;
            }, 10).run();
        }
    }
}

@Test
public void testOne() {
    DirectedGraph<String, DefaultEdge> g = DefaultDirectedGraph.create();
    g.addVertex("A");
    g.addVertex("B");
    g.addVertex("C");
    g.addVertex("D");
    g.addVertex("E");
    g.addVertex("F");
    g.addEdge("A", "B");
    g.addEdge("B", "C");
    g.addEdge("D", "C");
    g.addEdge("C", "D");
    g.addEdge("E", "F");
    g.addEdge("C", "C");
    assertEquals("[A, B, C, D]", shortestPath(g, "A", "D").toString());
    g.addEdge("B", "D");
    assertEquals("[A, B, D]", shortestPath(g, "A", "D").toString());
    assertNull("There is no path from A to E", shortestPath(g, "A", "E"));
    assertEquals("[]", shortestPath(g, "D", "D").toString());
    assertNull("Node X is not in the graph", shortestPath(g, "X", "A"));
    assertEquals("[[A, B, C, D], [A, B, D]]", paths(g, "A", "D").toString());
}

@Test
public void testVertexMustExist() {
    DirectedGraph<String, DefaultEdge> g = DefaultDirectedGraph.create();
    final boolean b = g.addVertex("A");
    assertTrue(b);
    final boolean b2 = g.addVertex("A");
    assertFalse(b2);
    try {
        DefaultEdge x = g.addEdge("A", "B");
        fail("expected exception, got " + x);
    } catch (IllegalArgumentException e) {
        // ok
    }
    g.addVertex("B");
    DefaultEdge x = g.addEdge("A", "B");
    assertNotNull(x);
    DefaultEdge x2 = g.addEdge("A", "B");
    assertNull(x2);
    try {
        DefaultEdge x3 = g.addEdge("Z", "A");
        fail("expected exception, got " + x3);
    } catch (IllegalArgumentException e) {
        // ok
    }
    g.addVertex("Z");
    DefaultEdge x3 = g.addEdge("Z", "A");
    assertNotNull(x3);
    DefaultEdge x4 = g.addEdge("Z", "A");
    assertNull(x4);
    // Attempting to add a vertex already present does not change the graph.
    final List<DefaultEdge> in1 = g.getInwardEdges("A");
    final List<DefaultEdge> out1 = g.getOutwardEdges("A");
    final boolean b3 = g.addVertex("A");
    assertFalse(b3);
    final List<DefaultEdge> in2 = g.getInwardEdges("A");
    final List<DefaultEdge> out2 = g.getOutwardEdges("A");
    assertEquals(in1, in2);
    assertEquals(out1, out2);
}

