@Test
public void testPosetBitsLarge2() {
    Assume.assumeTrue("too slow to run every day", CalciteSystemProperty.TEST_SLOW.value());
    final int n = 30000;
    final PartiallyOrderedSet<Integer> poset = new PartiallyOrderedSet<>(PartiallyOrderedSetTest::isBitSuperset, (Function<Integer, Iterable<Integer>>) i -> {
        int r = Objects.requireNonNull(i);
        final List<Integer> list = new ArrayList<>();
        for (int z = 1; r != 0; z <<= 1) {
            if ((i & z) != 0) {
                list.add(i ^ z);
                r ^= z;
            }
        }
        return list;
    }, // bits not yet cleared
    i -> {
        Objects.requireNonNull(i);
        final List<Integer> list = new ArrayList<>();
        for (int z = 1; z <= n; z <<= 1) {
            if ((i & z) == 0) {
                list.add(i | z);
            }
        }
        return list;
    });
    checkPosetBitsLarge(poset, n, 2921, 11961);
}

