@Test
public void testSpecial() {
    // price > 5 and price between 1 + 2 and 3 * 4 and price is null
    final PrecedenceClimbingParser p = new PrecedenceClimbingParser.Builder().atom("price").infix(">", 4, true).atom("5").infix("and", 2, true).atom("price").special("between", 3, 3, (parser, op) -> new PrecedenceClimbingParser.Result(op.previous, op.next.next.next, parser.call(op, ImmutableList.of(op.previous, op.next, op.next.next.next)))).atom("1").infix("+", 5, true).atom("2").infix("and", 2, true).atom("3").infix("*", 6, true).atom("4").infix("and", 2, true).atom("price").postfix("is null", 4).build();
    final PrecedenceClimbingParser.Token token = p.parse();
    assertThat(p.print(token), is("(((price > 5) and between(price, (1 + 2), (3 * 4)))" + " and (price is null))"));
}

@Test
public void testEqualPrecedence() {
    // LIKE has same precedence as '='; LIKE is right-assoc, '=' is left
    final PrecedenceClimbingParser p = new PrecedenceClimbingParser.Builder().atom("a").infix("=", 3, true).atom("b").infix("like", 3, false).atom("c").infix("=", 3, true).atom("d").build();
    final PrecedenceClimbingParser.Token token = p.parse();
    assertThat(p.print(token), is("(((a = b) like c) = d)"));
}

