/**
 * Tests that distinct-count is pushed down to Druid and evaluated using
 * "cardinality". The result is approximate, but gives the correct result in
 * this example when rounded down using FLOOR.
 */
@Test
public void testDistinctCount() {
    final String sql = "select \"state_province\",\n" + " floor(count(distinct \"city\")) as cdc\n" + "from \"foodmart\"\n" + "group by \"state_province\"\n" + "order by 2 desc limit 2";
    final String explain = "PLAN=EnumerableInterpreter\n" + "  BindableSort(sort0=[$1], dir0=[DESC], fetch=[2])\n" + "    BindableProject(state_province=[$0], CDC=[FLOOR($1)])\n" + "      BindableAggregate(group=[{1}], agg#0=[COUNT($0)])\n" + "        DruidQuery(table=[[foodmart, foodmart]], " + "intervals=[[1900-01-09T00:00:00.000Z/2992-01-10T00:00:00.000Z]], groups=[{29, 30}], " + "aggs=[[]])";
    final String druidQuery = "{'queryType':'groupBy','dataSource':'foodmart'," + "'granularity':'all','dimensions':[{'type':'default','dimension':'city','outputName':'city'" + ",'outputType':'STRING'}," + "{'type':'default','dimension':'state_province','outputName':'state_province','outputType':'STRING'}]," + "'limitSpec':{'type':'default'},'aggregations':[]," + "'intervals':['1900-01-09T00:00:00.000Z/2992-01-10T00:00:00.000Z']}";
    sql(sql).explainContains(explain).queryContains(druidChecker(druidQuery)).returnsUnordered("state_province=CA; CDC=45", "state_province=WA; CDC=22");
}

