 */
@Test
public void testCountDistinctOnComplexColumn() {
    // Because approximate distinct count has not been enabled
    sql("select count(distinct \"user_id\") from \"wiki\"", WIKI).failsAtValidation("Rolled up column 'user_id' is not allowed in COUNT");
    foodmartApprox("select count(distinct \"customer_id\") from \"foodmart\"").// customer_id gets transformed into it's actual underlying sketch column,
    // customer_id_ts. The thetaSketch aggregation is used to compute the count distinct.
    queryContains(druidChecker("{'queryType':'timeseries','dataSource':" + "'foodmart','descending':false,'granularity':'all','aggregations':[{'type':" + "'thetaSketch','name':'EXPR$0','fieldName':'customer_id_ts'}]," + "'intervals':['1900-01-09T00:00:00.000Z/2992-01-10T00:00:00.000Z']," + "'context':{'skipEmptyBuckets':false}}")).returnsUnordered("EXPR$0=5581");
    foodmartApprox("select sum(\"store_sales\"), " + "count(distinct \"customer_id\") filter (where \"store_state\" = 'CA') " + "from \"foodmart\" where \"the_month\" = 'October'").// Check that filtered aggregations work correctly
    queryContains(druidChecker("{'type':'filtered','filter':" + "{'type':'selector','dimension':'store_state','value':'CA'},'aggregator':" + "{'type':'thetaSketch','name':'EXPR$1','fieldName':'customer_id_ts'}}]")).returnsUnordered("EXPR$0=42342.26999999995; EXPR$1=459");
}

/**
 * Tests the use of other aggregations with complex columns
 */
@Test
public void testAggregationsWithComplexColumns() {
    wikiApprox("select count(\"user_id\") from \"wiki\"").failsAtValidation("Rolled up column 'user_id' is not allowed in COUNT");
    wikiApprox("select sum(\"user_id\") from \"wiki\"").failsAtValidation("Cannot apply 'SUM' to arguments of type " + "'SUM(<VARBINARY>)'. Supported form(s): 'SUM(<NUMERIC>)'");
    wikiApprox("select avg(\"user_id\") from \"wiki\"").failsAtValidation("Cannot apply 'AVG' to arguments of type " + "'AVG(<VARBINARY>)'. Supported form(s): 'AVG(<NUMERIC>)'");
    wikiApprox("select max(\"user_id\") from \"wiki\"").failsAtValidation("Rolled up column 'user_id' is not allowed in MAX");
    wikiApprox("select min(\"user_id\") from \"wiki\"").failsAtValidation("Rolled up column 'user_id' is not allowed in MIN");
}

/**
 * Test post aggregation support with +, -, /, * operators
 */
@Test
public void testPostAggregationWithComplexColumns() {
    foodmartApprox("select " + "(count(distinct \"customer_id\") * 2) + " + "count(distinct \"customer_id\") - " + "(3 * count(distinct \"customer_id\")) " + "from \"foodmart\"").queryContains(druidChecker("\"postAggregations\":[{\"type\":\"expression\"," + "\"name\":\"EXPR$0\",\"expression\":\"(((\\\"$f0\\\" * 2) + \\\"$f0\\\")" + " - (3 * \\\"$f0\\\"))\"}]")).returnsUnordered("EXPR$0=0");
    foodmartApprox("select " + "\"the_month\" as \"month\", " + "sum(\"store_sales\") / count(distinct \"customer_id\") as \"avg$\" " + "from \"foodmart\" group by \"the_month\"").queryContains(druidChecker("'postAggregations':[{'type':'expression'," + "'name':'avg$','expression':'(\\'$f1\\' / \\'$f2\\')'}]")).returnsUnordered("month=January; avg$=32.62155444126063", "month=February; avg$=33.102021036814484", "month=March; avg$=33.84970906630567", "month=April; avg$=32.557517084282296", "month=May; avg$=32.42617797228287", "month=June; avg$=33.93093562874239", "month=July; avg$=34.36859097127213", "month=August; avg$=32.81181818181806", "month=September; avg$=33.327733840304155", "month=October; avg$=32.74730858468674", "month=November; avg$=34.51727684346705", "month=December; avg$=33.62788665879565");
    final String druid = "'postAggregations':[{'type':'expression','name':'EXPR$0'," + "'expression':'((\\'$f0\\' + 100) - (\\'$f0\\' * 2))'}]";
    final String sql = "select (count(distinct \"user_id\") + 100) - " + "(count(distinct \"user_id\") * 2) from \"wiki\"";
    wikiApprox(sql).queryContains(druidChecker(druid)).returnsUnordered("EXPR$0=-10590");
    // Change COUNT(DISTINCT ...) to APPROX_COUNT_DISTINCT(...) and get
    // same result even if approximation is off by default.
    final String sql2 = "select (approx_count_distinct(\"user_id\") + 100) - " + "(approx_count_distinct(\"user_id\") * 2) from \"wiki\"";
    sql(sql2, WIKI).queryContains(druidChecker(druid)).returnsUnordered("EXPR$0=-10590");
}

/**
