@Test
public void testPushEqualsCastDimension() {
    final String sqlQuery = "select sum(\"store_cost\") as a " + "from \"foodmart\" " + "where cast(\"product_id\" as double) = 1016.0";
    final String plan = "PLAN=EnumerableInterpreter\n" + "  DruidQuery(table=[[foodmart, foodmart]], intervals=[[1900-01-09T00:00:00.000Z/2992-01-10T00:00:00.000Z]], " + "filter=[=(CAST($1):DOUBLE, 1016.0)], groups=[{}], aggs=[[SUM($91)]])";
    final String druidQuery = "{'queryType':'timeseries','dataSource':'foodmart','descending':false,'granularity':'all'," + "'filter':{'type':'bound','dimension':'product_id','lower':'1016.0'," + "'lowerStrict':false,'upper':'1016.0','upperStrict':false,'ordering':'numeric'}," + "'aggregations':[{'type':'doubleSum','name':'A','fieldName':'store_cost'}]," + "'intervals':['1900-01-09T00:00:00.000Z/2992-01-10T00:00:00.000Z']," + "'context':{'skipEmptyBuckets':false}}";
    sql(sqlQuery, FOODMART).explainContains(plan).queryContains(druidChecker(druidQuery)).returnsUnordered("A=85.31639999999999");
    final String sqlQuery2 = "select sum(\"store_cost\") as a " + "from \"foodmart\" " + "where cast(\"product_id\" as double) <= 1016.0 " + "and cast(\"product_id\" as double) >= 1016.0";
    sql(sqlQuery2, FOODMART).returnsUnordered("A=85.31639999999999");
}

