 * Druid "select" query.
 */
@Test
public void testFilterSortDesc() {
    final String sql = "select \"product_name\" from \"foodmart\"\n" + "where \"product_id\" BETWEEN '1500' AND '1502'\n" + "order by \"state_province\" desc, \"product_id\"";
    final String druidQuery = "{'queryType':'scan','dataSource':'foodmart'," + "'intervals':['1900-01-09T00:00:00.000Z/2992-01-10T00:00:00.000Z']," + "'filter':{'type':'and','fields':[" + "{'type':'bound','dimension':'product_id','lower':'1500','lowerStrict':false,'ordering':'lexicographic'}," + "{'type':'bound','dimension':'product_id','upper':'1502','upperStrict':false,'ordering':'lexicographic'}]}," + "'columns':['product_name','state_province','product_id']," + "'resultFormat':'compactedList'";
    sql(sql).limit(4).returns(resultSet -> {
        try {
            for (int i = 0; i < 4; i++) {
