    CalciteAssert.that().with(newConnectionFactory()).// by default elastic returns max 10 records
    query("select * from elastic.zips").runs();
    CalciteAssert.that().with(newConnectionFactory()).query("select * from elastic.zips where _MAP['city'] = 'BROOKLYN'").returnsCount(1);
    CalciteAssert.that().with(newConnectionFactory()).query("select * from elastic.zips where" + " _MAP['city'] in ('BROOKLYN', 'WASHINGTON')").returnsCount(2);
