/**
 * Test that {@code _id} field is available when queried explicitly.
 * @see <a href="https://www.elastic.co/guide/en/elasticsearch/reference/current/mapping-id-field.html">ID Field</a>
 */
@Test
public void projectionWithIdField() {
    final CalciteAssert.AssertThat factory = CalciteAssert.that().with(newConnectionFactory());
    factory.query("select \"id\" from view").returns(regexMatch("id=\\p{Graph}+"));
    factory.query("select \"id\", \"id\" from view").returns(regexMatch("id=\\p{Graph}+; id=\\p{Graph}+"));
    factory.query("select \"id\", \"a\" from view").returns(regexMatch("id=\\p{Graph}+; a=1"));
    factory.query("select \"a\", \"id\" from view").returns(regexMatch("a=1; id=\\p{Graph}+"));
    // single _id column
    final String sql1 = String.format(Locale.ROOT, "select _MAP['_id'] " + " from \"elastic\".\"%s\"", NAME);
    factory.query(sql1).returns(regexMatch("EXPR$0=\\p{Graph}+"));
    // multiple columns: _id and a
    final String sql2 = String.format(Locale.ROOT, "select _MAP['_id'], _MAP['a'] " + " from \"elastic\".\"%s\"", NAME);
    factory.query(sql2).returns(regexMatch("EXPR$0=\\p{Graph}+; EXPR$1=1"));
    // multiple _id columns
    final String sql3 = String.format(Locale.ROOT, "select _MAP['_id'], _MAP['_id'] " + " from \"elastic\".\"%s\"", NAME);
    factory.query(sql3).returns(regexMatch("EXPR$0=\\p{Graph}+; EXPR$1=\\p{Graph}+"));
    // _id column with same alias
    final String sql4 = String.format(Locale.ROOT, "select _MAP['_id'] as \"_id\" " + " from \"elastic\".\"%s\"", NAME);
    factory.query(sql4).returns(regexMatch("_id=\\p{Graph}+"));
    // _id field not available implicitly
    factory.query(String.format(Locale.ROOT, "select * from \"elastic\".\"%s\"", NAME)).returns(regexMatch("_MAP={a=1, b={a=2, b=3, c={a=foo}}}"));
    factory.query(String.format(Locale.ROOT, "select *, _MAP['_id'] from \"elastic\".\"%s\"", NAME)).returns(regexMatch("_MAP={a=1, b={a=2, b=3, c={a=foo}}}; EXPR$1=\\p{Graph}+"));
}

/**
