 * <a href="https://www.elastic.co/guide/en/elasticsearch/reference/current/modules-scripting.html">scripting</a>
 * should be used just
 * <a href="https://www.elastic.co/guide/en/elasticsearch/reference/current/search-request-source-filtering.html">_source</a>
 */
@Test
public void simpleProjectionNoScripting() {
    CalciteAssert.that().with(newConnectionFactory()).query(String.format(Locale.ROOT, "select _MAP['_id'], _MAP['a'], _MAP['b.a'] from " + " \"elastic\".\"%s\" where _MAP['b.a'] = 2", NAME)).queryContains(ElasticsearchChecker.elasticsearchChecker("'query.constant_score.filter.term.b.a':2", "_source:['a', 'b.a']", "size:5196")).returns(regexMatch("EXPR$0=\\p{Graph}+; EXPR$1=1; EXPR$2=2"));
}

