/**
 * Test for simple scalar terms (boolean, int etc.)
 * @throws Exception not expected
 */
@Test
public void term() throws Exception {
    assertEquals("{\"term\":{\"foo\":\"bar\"}}", toJson(QueryBuilders.termQuery("foo", "bar")));
    assertEquals("{\"term\":{\"bar\":\"foo\"}}", toJson(QueryBuilders.termQuery("bar", "foo")));
    assertEquals("{\"term\":{\"foo\":\"A\"}}", toJson(QueryBuilders.termQuery("foo", 'A')));
    assertEquals("{\"term\":{\"foo\":true}}", toJson(QueryBuilders.termQuery("foo", true)));
    assertEquals("{\"term\":{\"foo\":false}}", toJson(QueryBuilders.termQuery("foo", false)));
    assertEquals("{\"term\":{\"foo\":0}}", toJson(QueryBuilders.termQuery("foo", (byte) 0)));
    assertEquals("{\"term\":{\"foo\":123}}", toJson(QueryBuilders.termQuery("foo", (long) 123)));
    assertEquals("{\"term\":{\"foo\":41}}", toJson(QueryBuilders.termQuery("foo", (short) 41)));
    assertEquals("{\"term\":{\"foo\":42.42}}", toJson(QueryBuilders.termQuery("foo", 42.42D)));
    assertEquals("{\"term\":{\"foo\":1.1}}", toJson(QueryBuilders.termQuery("foo", 1.1F)));
    assertEquals("{\"term\":{\"foo\":1}}", toJson(QueryBuilders.termQuery("foo", new BigDecimal(1))));
    assertEquals("{\"term\":{\"foo\":121}}", toJson(QueryBuilders.termQuery("foo", new BigInteger("121"))));
    assertEquals("{\"term\":{\"foo\":111}}", toJson(QueryBuilders.termQuery("foo", new AtomicLong(111))));
    assertEquals("{\"term\":{\"foo\":222}}", toJson(QueryBuilders.termQuery("foo", new AtomicInteger(222))));
    assertEquals("{\"term\":{\"foo\":true}}", toJson(QueryBuilders.termQuery("foo", new AtomicBoolean(true))));
}

@Test
public void terms() throws Exception {
    assertEquals("{\"terms\":{\"foo\":[]}}", toJson(QueryBuilders.termsQuery("foo", Collections.emptyList())));
    assertEquals("{\"terms\":{\"bar\":[]}}", toJson(QueryBuilders.termsQuery("bar", Collections.emptySet())));
    assertEquals("{\"terms\":{\"singleton\":[0]}}", toJson(QueryBuilders.termsQuery("singleton", Collections.singleton(0))));
    assertEquals("{\"terms\":{\"foo\":[true]}}", toJson(QueryBuilders.termsQuery("foo", Collections.singleton(true))));
    assertEquals("{\"terms\":{\"foo\":[\"bar\"]}}", toJson(QueryBuilders.termsQuery("foo", Collections.singleton("bar"))));
    assertEquals("{\"terms\":{\"foo\":[\"bar\"]}}", toJson(QueryBuilders.termsQuery("foo", Collections.singletonList("bar"))));
    assertEquals("{\"terms\":{\"foo\":[true,false]}}", toJson(QueryBuilders.termsQuery("foo", Arrays.asList(true, false))));
    assertEquals("{\"terms\":{\"foo\":[1,2,3]}}", toJson(QueryBuilders.termsQuery("foo", Arrays.asList(1, 2, 3))));
    assertEquals("{\"terms\":{\"foo\":[1.1,2.2,3.3]}}", toJson(QueryBuilders.termsQuery("foo", Arrays.asList(1.1, 2.2, 3.3))));
}

@Test
public void boolQuery() throws Exception {
    QueryBuilders.QueryBuilder q1 = QueryBuilders.boolQuery().must(QueryBuilders.termQuery("foo", "bar"));
    assertEquals("{\"bool\":{\"must\":{\"term\":{\"foo\":\"bar\"}}}}", toJson(q1));
    QueryBuilders.QueryBuilder q2 = QueryBuilders.boolQuery().must(QueryBuilders.termQuery("f1", "v1")).must(QueryBuilders.termQuery("f2", "v2"));
