/**
 * Unit test for {@link Functions#filter}.
 */
@Test
public void testFilter() {
    final List<String> abc = Arrays.asList("A", "B", "C", "D");
    // a miss, then a hit
    Assert.assertEquals("[A, C, D]", Functions.filter(abc, v1 -> !v1.equals("B")).toString());
    // a hit, then all misses
    Assert.assertEquals("[A]", Functions.filter(abc, v1 -> v1.equals("A")).toString());
    // two hits, then a miss
    Assert.assertEquals("[A, B, D]", Functions.filter(abc, v1 -> !v1.equals("C")).toString());
    Assert.assertSame(Collections.emptyList(), Functions.filter(abc, Functions.falsePredicate1()));
    Assert.assertSame(abc, Functions.filter(abc, Functions.truePredicate1()));
}

/**
 * Unit test for {@link Functions#exists}.
 */
@Test
public void testExists() {
    final List<Integer> ints = Arrays.asList(1, 10, 2);
    final List<Integer> empty = Collections.emptyList();
    Assert.assertFalse(Functions.exists(ints, v1 -> v1 > 20));
    Assert.assertFalse(Functions.exists(empty, Functions.falsePredicate1()));
    Assert.assertFalse(Functions.exists(empty, Functions.truePredicate1()));
}

/**
 * Unit test for {@link Functions#all}.
 */
@Test
public void testAll() {
    final List<Integer> ints = Arrays.asList(1, 10, 2);
    final List<Integer> empty = Collections.emptyList();
    Assert.assertFalse(Functions.all(ints, v1 -> v1 > 20));
    Assert.assertTrue(Functions.all(ints, v1 -> v1 < 20));
    Assert.assertFalse(Functions.all(ints, v1 -> v1 < 10));
    Assert.assertTrue(Functions.all(empty, Functions.falsePredicate1()));
    Assert.assertTrue(Functions.all(empty, Functions.truePredicate1()));
}

