    String s = Linq4j.asEnumerable(depts).groupJoin(Linq4j.asEnumerable(emps).concat(Linq4j.asEnumerable(badEmps)), DEPT_DEPTNO_SELECTOR, EMP_DEPTNO_SELECTOR, (v1, v2) -> {
        final StringBuilder buf = new StringBuilder("[");
        int n = 0;
        for (Employee employee : v2) {
            if (n++ > 0) {
                buf.append(", ");
            }
            buf.append(employee.name);
        }
        return buf.append("] work(s) in ").append(v1.name).toString();
    }).toList().toString();
    assertEquals("[[Fred, Eric, Janet] work(s) in Sales, " + "[] work(s) in HR, " + "[Bill] work(s) in Marketing]", s);
}

