@Test
public void testCartesianProductEnumerator() {
    final Enumerable<String> abc = Linq4j.asEnumerable(Arrays.asList("a", "b", "c"));
    final Enumerable<String> xy = Linq4j.asEnumerable(Arrays.asList("x", "y"));
    final Enumerator<List<String>> productEmpty = Linq4j.product(Arrays.<Enumerator<String>>asList());
    assertTrue(productEmpty.moveNext());
    assertEquals(Arrays.<String>asList(), productEmpty.current());
    assertFalse(productEmpty.moveNext());
    final Enumerator<List<String>> product0 = Linq4j.product(Arrays.asList(Linq4j.emptyEnumerator()));
    assertFalse(product0.moveNext());
    final Enumerator<List<String>> productFullEmpty = Linq4j.product(Arrays.asList(abc.enumerator(), Linq4j.emptyEnumerator()));
    assertFalse(productFullEmpty.moveNext());
    final Enumerator<List<String>> productEmptyFull = Linq4j.product(Arrays.asList(abc.enumerator(), Linq4j.emptyEnumerator()));
    assertFalse(productEmptyFull.moveNext());
    final Enumerator<List<String>> productAbcXy = Linq4j.product(Arrays.asList(abc.enumerator(), xy.enumerator()));
    assertTrue(productAbcXy.moveNext());
    assertEquals(Arrays.asList("a", "x"), productAbcXy.current());
    assertTrue(productAbcXy.moveNext());
    assertEquals(Arrays.asList("a", "y"), productAbcXy.current());
    assertTrue(productAbcXy.moveNext());
    assertEquals(Arrays.asList("b", "x"), productAbcXy.current());
    assertTrue(productAbcXy.moveNext());
    assertTrue(productAbcXy.moveNext());
    assertTrue(productAbcXy.moveNext());
    assertFalse(productAbcXy.moveNext());
}

@Test
public void testAsQueryable() {
    // "count" is an Enumerable method.
    final int n = Linq4j.asEnumerable(emps).asQueryable().count();
    assertEquals(4, n);
    // "where" is a Queryable method
    // first, use a lambda
    ParameterExpression parameter = Expressions.parameter(Employee.class);
    final Queryable<Employee> nh = Linq4j.asEnumerable(emps).asQueryable().where(Expressions.lambda(Predicate1.class, Expressions.equal(Expressions.field(parameter, Employee.class, "deptno"), Expressions.constant(10)), parameter));
    assertEquals(3, nh.count());
    // second, use an expression
    final Queryable<Employee> nh2 = Linq4j.asEnumerable(emps).asQueryable().where(Expressions.lambda(v1 -> v1.deptno == 10));
    assertEquals(3, nh2.count());
    // use lambda, this time call whereN
    ParameterExpression parameterE = Expressions.parameter(Employee.class);
    ParameterExpression parameterN = Expressions.parameter(Integer.TYPE);
    final Queryable<Employee> nh3 = Linq4j.asEnumerable(emps).asQueryable().whereN(Expressions.lambda((Class<Predicate2<Employee, Integer>>) (Class) Predicate2.class, Expressions.andAlso(Expressions.equal(Expressions.field(parameterE, Employee.class, "deptno"), Expressions.constant(10)), Expressions.lessThan(parameterN, Expressions.constant(3))), parameterE, parameterN));
    assertEquals(2, nh3.count());
}

