    checkSql("select p.\"product_name\", /*s.\"product_id\",*/ s.\"action\"\n" + "from \"splunk\".\"splunk\" as s\n" + "join \"foodmart\".\"product\" as p\n" + "on cast(s.\"product_id\" as integer) = p.\"product_id\"\n" + "where s.\"action\" = 'PURCHASE'", null);
}

@Test
public void testGroupBy() throws SQLException {
    checkSql("select s."host", count("source") as c
" + "from "splunk"."splunk" as s
" + "group by s."host"
" + "order by c desc
", expect("host=vendor_sales; C=30244", "host=www1; C=24221", "host=www3; C=22975", "host=www2; C=22595", "host=mailsv; C=9829"));
}
